(window.RAGHIB = window.RAGHIB || {})["2-8"] = [
  {"a": [205, 205], "h": "\"Allah does not love corruption\" — then what of the decay and death He brings? \"O You whose undoing is a mending\"", "hAr": "﴿وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ﴾ — فما بال ما يفنيه؟ «يا من إفساده إصلاح»", "said": "بين تعالى حال هذا المعجب في الدنيا المرائي المجادل بأنه إذا تولى عمن يرائي سعى في الإفساد وإهلاك الحرث والنسل وذلك معاندة لله فيما حث عليه في قوله: ﴿وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾ ... إن قيل: كيف حكم تعالى بأنه لا يحب الفساد وهو مفسد للأشياء؟ قيل: الإفساد في الحقيقة إخراج الشيء من حالة محمودة لا لغرض صحيح، وذلك غير موجود في فعل الله تعالى، ولا هو أمر به ولا محب له، وما يراه من فعله، [ويظهر بظاهره] فسادا فهو بالإضافة إلينا ولاعتبار ما، فأما بالنظر الإلهي فكله صلاح، ولهذا قال بعض الحكماء: \" يا من إفساده إصلاح \"، أي ما نظنه إفسادا لقصور نظرنا ومعرفتنا فهو في الحقيقة إصلاح وجملة الأمر أن الإنسان هو زبدة هذا العالم، وما عداه مخلوق لأجله، ولهذا قال تعالى: ﴿هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا﴾، والمقصد من الإنسان سوقه إلى كماله الذي رشح له، فإذن إهلاك ما أمر بإهلاكه فلإصلاح الإنسان، وأما إماتته، فأحد أسباب حياته الأبدية", "en": "This man who impresses people with his worldly talk, the show-off and quarreller — once he turns away from those he performs for, he hurries to spread corruption and destroy crops and livestock. That is defiance of Allah, who called people to build the earth: \"He… settled you in it\". And \"Allah does not love corruption\": He is not pleased with such a deed.\nBut does Allah not \"undo\" things Himself — decay, destruction, death? Ar-Raghib: corruption in reality is taking a thing out of a good state for no sound purpose — and that is never found in what Allah does; He neither commands it nor loves it. Whatever of His acts looks like corruption looks so only in relation to us, from one angle; seen from the divine view, all of it is setting right. As a sage prayed: \"O You whose undoing is a mending\" — what our short sight takes for undoing is, in truth, repair.\nIn sum: the human being is the cream of this world, and everything else was created for him — \"He created for you all that is on the earth\". The aim for the human being is to carry him to the completeness he was prepared for. So when Allah brings to an end what He brings to an end, it is for the good of the human being; and his own death is one of the causes of his everlasting life.", "ar": "بيّن تعالى حال هذا المعجِب في الدنيا المرائي المجادل: إذا تولّى عمّن يرائيه سعى في الإفساد وإهلاك الحرث والنسل — وذلك معاندةٌ لله فيما حثّ عليه من العمارة: ﴿وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾ —، و﴿وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ﴾: لا يرضى فعله.\nفإن قيل: كيف لا يحبّ الفساد وهو يُفني الأشياء؟ قيل: الإفساد في الحقيقة إخراج الشيء من حالةٍ محمودة لا لغرضٍ صحيح، وذلك غير موجودٍ في فعل الله، ولا هو أمر به ولا محبٌّ له؛ وما يُرى من فعله فسادًا فهو بالإضافة إلينا ولاعتبارٍ ما، فأمّا بالنظر الإلهيّ فكلّه صلاح. ولهذا قال بعض الحكماء: «يا من إفساده إصلاح» — أي ما نظنّه إفسادًا لقصور نظرنا ومعرفتنا فهو في الحقيقة إصلاح.\nوجملة الأمر أن الإنسان زبدة هذا العالم، وما عداه مخلوقٌ لأجله: ﴿هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا﴾؛ والمقصد من الإنسان سوقه إلى كماله الذي رُشّح له؛ فإهلاك ما أمر بإهلاكه لإصلاح الإنسان، وأمّا إماتته فأحد أسباب حياته الأبديّة.", "links": [{"ref": "11:61", "q": "﴿هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾", "en": "Called to build, not ruin", "ar": "مدعوّون إلى العمارة لا الخراب"}, {"ref": "7:56", "q": "﴿وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا﴾", "en": "Do not spoil what was set right", "ar": "لا تفسدوا بعد الإصلاح"}, {"ref": "67:2", "q": "﴿ٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ﴾", "en": "Death as part of the design", "ar": "الموت من التدبير"}, {"ref": "2:29", "q": "﴿هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا﴾", "en": "All of it for the human being", "ar": "كلّه لأجل الإنسان"}], "v": 1, "p": 428, "pe": 429, "sid": 429},
  {"a": [206, 206], "h": "\"Pride seizes him in sin\" — and Hell called a \"resting place\"", "hAr": "﴿أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ﴾ — وجهنّم «مهادًا»", "said": "المهد معروف، وتصور منه التوطئة، فقيل لكل وطيء مهد ... وجعل جهنم مهادا لهم كما جعل العذاب مبشرا به في قوله: ﴿فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ﴾ وقوله: بالإثم أي بسبب الإثم وقيل: دعته العزة إلى أن يأثم، كقوله: أخذني بفعل كذا، أي بأن أفعله وبين أن جهنم نصيبه الكافي جزاؤه الوافي", "en": "When he is told \"be mindful of Allah\", pride seizes him \"in sin\" — either because of his sin, or pride drives him on to sin, as one says \"it made me do such-and-such\". Hell is enough for him — his full recompense. It is called his mihad, a bed laid out, with bitter irony — as punishment is called \"good news\" in \"give them good news of a painful punishment\". \"And what an evil resting place!\"", "ar": "﴿وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ﴾: بسبب الإثم، أو دعته العزّة إلى أن يأثم، كقولك «أخذني بفعل كذا» أي بأن أفعله. و﴿فَحَسۡبُهُۥ جَهَنَّمُۖ﴾: نصيبه الكافي وجزاؤه الوافي. و«المهاد» الفراش الموطّأ، وجعل جهنّم مهادًا لهم كما جعل العذاب مبشَّرًا به في قوله ﴿فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ﴾. ثم دلّ على حالها: ﴿وَلَبِئۡسَ ٱلۡمِهَادُ﴾.", "links": [{"ref": "38:2", "q": "﴿بَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةٖ وَشِقَاقٖ﴾", "en": "False pride", "ar": "العزّة الكاذبة"}, {"ref": "7:41", "q": "﴿لَهُم مِّن جَهَنَّمَ مِهَادٞ وَمِن فَوۡقِهِمۡ غَوَاشٖۚ﴾", "en": "The same \"bed\"", "ar": "«المهاد» نفسه"}], "v": 1, "p": 429, "pe": 430, "sid": 430},
  {"a": [207, 207], "h": "\"One who sells himself to seek Allah's pleasure\" — three kinds of people, and the best Owner", "hAr": "﴿وَمِنَ ٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِۚ﴾ — ثلاثة أصناف، وخير مالك", "said": "والناس على أضرب ضرب باع نفسه من الشيطان بالشهوات، فصار علقا [في] يده لا سبيل إلى الانفكاك منه، وهم المعنيون بقوله: ﴿فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ عَذَابٌ أَلِيمٞ﴾، وقوله: ﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾، وضرب وقع أسر الشيطان عليه، فاجتهد في تخليص نفسه منه وهو المعنى بقوله- عليه السلام: \" الناس غاديان، فبائع نفسه فموبقها، ومبتاع نفسه فمعتقها \"، وضرب لم يقع عليه أسر الشيطان، وقد باع نفسه من الله- عز وجل، وهو المعنى بقوله: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾ ... والشراء والبيع في مثل هذا الموضع كالرمز والإشارة، وحقيقتهما وقف الإنسان نفسه على مرضاة الله - عز وجل-، والتحري في مصالح عباده ... ونبه بقوله: ﴿وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ﴾، أن الإنسان في بيع نفسه منه تعالى يدخل في ملك من هو أرأف به من نفسه أولى به من ذاته", "en": "Yashri means both \"sells\" and \"buys\". And people, ar-Raghib says, are of three kinds. One sold himself to Satan for his appetites and became a pledge in his hand he cannot redeem — \"Satan made their deeds seem fair to them, so he is their protector today\", \"have you seen him who takes his desire as his god?\". Another fell into Satan's captivity and struggles to buy himself free — as the Prophet ﷺ said, \"every person goes out in the morning and sells himself: he either frees himself or ruins himself\". And another was never captured, and has sold himself to Allah — \"Allah has bought from the believers their selves and their wealth, in exchange for Paradise\".\n\"Sells himself\" covers both of the last two. The buying and selling here are a figure; their reality is a person devoting himself wholly to Allah's pleasure and to seeking the good of His servants. (It is reported to have come down about Suhayb, who gave his wealth to the idolaters of Makkah so that they would let him go and join the Prophet ﷺ; Abu Bakr told him: \"your trade has profited\".)\n\"And Allah is Kind to His servants\": whoever sells himself to Allah passes into the ownership of One who is kinder to him than he is to himself, and has more right to him than his own self.", "ar": "«يشري» يكون بمعنى يبيع ويشتري. والناس أضرب: ضربٌ باع نفسه للشيطان بالشهوات فصار رهنًا في يده لا سبيل له إلى الانفكاك — ﴿فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ﴾، ﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾ —؛ وضربٌ وقع عليه أسر الشيطان فاجتهد في تخليص نفسه — وهو المعنيّ بقوله ﷺ: «الناس غاديان: فبائعٌ نفسه فموبقها، ومبتاعٌ نفسه فمعتقها» —؛ وضربٌ لم يقع عليه أسر الشيطان وقد باع نفسه لله: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾.\nفـ﴿يَشۡرِي نَفۡسَهُ﴾ يتناول الضربين الأخيرين: المخلّص نفسه من أسر الشيطان، والبائع نفسه لله. والشراء والبيع هنا كالرمز والإشارة، وحقيقتهما وقف الإنسان نفسه على مرضاة الله، والتحرّي في مصالح عباده. (وقيل نزلت في صهيب، أعطى المشركين ماله ليخلّوا سبيله إلى المدينة، فقال له أبو بكر: ربح البيع.)\nو﴿وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ﴾: الإنسان في بيع نفسه لله يدخل في ملك من هو أرأف به من نفسه، وأولى به من ذاته.", "links": [{"ref": "9:111", "q": "﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾", "en": "The sale to Allah", "ar": "البيع لله"}, {"ref": "16:63", "q": "﴿فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ﴾", "en": "Sold to Satan", "ar": "المبيع للشيطان"}, {"ref": "2:131", "q": "﴿إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾", "en": "Allah's captive is the free one", "ar": "أسير الرحمن هو الحرّ"}], "v": 1, "p": 430, "pe": 431, "sid": 431},
  {"a": [208, 208], "h": "\"Enter into peace, all of you\" — the three levels of making peace with Allah", "hAr": "﴿ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةٗ﴾ — منازل السِّلم مع الله الثلاث", "said": "عنى بالسلم سلم العبد لله - عز وجل، وذلك أن الإنسان في كفره، وكفران نعمة الله كالمحارب له، ولهذا يسمى الكافر المحارب في نحو قوله: ﴿ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ﴾، وسلم العباد لله على ثلاثة أضرب، ضرب يتقدمه إلى الإيمان وهو الإسلام الذي سلم به من الله أن يراق دمه ويسلب ماله وهو المعني بقوله- عليه السلام: \" أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله، فإذا قالوها عصموا مني دماءهم وأموالهم \". واثنان بعد الإيمان، أحدهما أن يسلم من سخطه بارتسام أوامره وزواجره طوعا أو كرها، والثاني: أن يكون سليما من الشيطان وأوليائه، وسليما فيما يجري من قضائه، وبه يحصل [دار السلام المذكورة في قوله تعالى]: ﴿وَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ﴾ وهذا غاية ما ينتهي إليه للعبد من المنازل الثلاث وإن كان لكل منزلة منها درجات", "en": "\"Peace\" here is the servant's peace with Allah. For a person in disbelief and ingratitude to Allah's favours is like one at war with Him — hence the words \"those who wage war against Allah and His Messenger\".\nMaking peace with Allah has three levels. The first comes before faith and leads to it: the Islam by which a person's life and property are protected — \"I have been commanded to fight people until they say 'there is no god but Allah'; when they say it, their blood and wealth are protected from me\". Two come after faith: being safe from His displeasure, by following His commands and prohibitions, willingly or unwillingly; and being whole and at peace — safe from Satan and his allies, and at peace with whatever His decree brings. By this last one reaches \"the Home of Peace\" to which Allah invites. That is the furthest the servant can reach, though each level has degrees within it. It is the Islam of \"the religion with Allah is Islam\", and the Islam Yusuf asked for: \"take my soul as a Muslim\".\n\"All of you — completely\": and following Satan is stepping out of that peace; his enmity is plain.", "ar": "عنى بالسِّلم سِلم العبد لله؛ فالإنسان في كفره وكفرانه نعمة الله كالمحارب له، ولهذا سُمّي الكافر محاربًا في نحو قوله ﴿ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ﴾.\nوسِلم العباد لله على ثلاثة أضرب: ضربٌ يتقدّم الإيمان ويؤدّي إليه — الإسلام الذي يُعصم به الدم والمال، وهو المعنيّ بقوله ﷺ: «أُمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله، فإذا قالوها عصموا منّي دماءهم وأموالهم» —؛ واثنان بعد الإيمان: أن يسلم من سخطه بارتسام أوامره وزواجره طوعًا أو كرهًا؛ وأن يكون سليمًا من الشيطان وأوليائه، راضيًا بما يجري من قضائه — وبه تُنال دار السلام: ﴿وَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ﴾. وهذا غاية ما ينتهي إليه العبد من المنازل الثلاث، وإن كان لكلّ منزلةٍ درجات؛ وهو المعنيّ بقوله ﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ﴾، والذي تمنّاه يوسف: ﴿تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾.\nو﴿وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ﴾: اتّباعه خروجٌ عن السِّلم، وعداوته لا تخفى.", "links": [{"ref": "10:25", "q": "﴿وَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ﴾", "en": "The Home of Peace", "ar": "دار السلام"}, {"ref": "2:112", "q": "﴿بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ﴾", "en": "The same levels of Islam, earlier", "ar": "منازل الإسلام نفسها قبلُ"}, {"ref": "3:19", "q": "﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ﴾", "en": "The religion with Allah", "ar": "الدين عند الله"}], "v": 1, "p": 432, "pe": 432, "sid": 433},
  {"a": [209, 209], "h": "\"If you slip after the clear proofs came\" — what to remember when a sin tempts you", "hAr": "﴿فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ﴾ — ما تذكره حين تهمّ بذنب", "said": "زل وزال يتقاربان، ولكن زال أبلغ، ولفظ البينات عام فيما حولنا من المعارف العقلية والسمعية ... ونبه بقوله ﴿بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ﴾ أن أعظم الذنبين ما كان بعد المعرفة والبينة، وفي هذا تحذير لمن يبصر عن ركوب ذنب فكأنه قيل: إذا أردتم ذنبا فاذكروا عز الله وحكمته، [ففي العلم بعزه علم بقدرته على عقاب المذنب]، وفي العلم بحكمته علم بأنه غير ظالم في عقابه وفي العلم بهذين انزجار عن ارتكاب الذنب", "en": "\"Clear proofs\" covers all the knowledge we have been given, from reason and from revelation. And \"after the clear proofs came\" shows that the graver of two sins is the one committed after knowledge and proof. (A person never means to slip; the warning is against setting out on the act where slipping happens.)\nSo it is a warning to anyone who sees clearly: when you are about to sin, remember that Allah is Mighty and Wise. Knowing His might, you know He is able to punish the sinner; knowing His wisdom, you know He does no injustice in punishing. Knowing both is what holds a person back from the sin.", "ar": "«زلّ» و«زال» متقاربان، و«زال» أبلغ. و«البيّنات» عامٌّ فيما خُوّلناه من المعارف العقليّة والسمعيّة. والنهي عن الزلّة نهيٌ عن القصد إلى الفعل الذي تحصل عنده الزلّة، إذ الإنسان لا يقصد أن يزلّ.\nونبّه بقوله ﴿مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ﴾ أن أعظم الذنبين ما كان بعد المعرفة والبيّنة. وفيه تحذيرٌ لمن يبصر من ركوب الذنب: فكأنه قيل: إذا أردتم ذنبًا فاذكروا عزّة الله وحكمته: ففي العلم بعزّته علمٌ بقدرته على عقاب المذنب، وفي العلم بحكمته علمٌ بأنه غير ظالمٍ في عقابه، وفي العلم بهما انزجارٌ عن ارتكاب الذنب.", "links": [{"ref": "3:105", "q": "﴿وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ﴾", "en": "Wrong done after knowledge", "ar": "الخطأ بعد العلم"}, {"ref": "2:211", "q": "﴿سَلۡ بَنِيٓ إِسۡرَٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةٖۗ﴾", "en": "The same warning, with an example", "ar": "التحذير نفسه بمثال"}], "v": 1, "p": 433, "pe": 433, "sid": 434},
  {"a": [210, 210], "h": "\"That Allah should come to them in shadows of cloud\" — how ar-Raghib reads Allah's \"coming\"", "hAr": "﴿أَن يَأۡتِيَهُمُ ٱللَّهُ فِي ظُلَلٖ مِّنَ ٱلۡغَمَامِ﴾ — كيف يفهم الراغب «إتيان» الله", "said": "قد تصور بعض الناس ما لا يليق بصفات الله تعالى في لفظ المجيء والإتيان الذي وصف الله - عز وجل به نفسه في هذه الآية ... وذلك لأمرين، أحدهما لقصورهم عن معرفة البارئ عز وجل، والثاني: لضيق مجالهم في مجاري الألفاظ ومجازها، وليس يقال الإتيان والمجئ لانتقال الحي المتحرك من مكان إلى مكان فقط، بل قد يقال لقصد القاصد بعنايته أمرا يستصلحه كقوله: أتيت المروة من بابها، [ويقال أيضا] لاستيفاء فعل يتولاه، كقولك: أتيت على ما في الكتاب ... ووجه آخر، قد أشير إليه في صدر الكتاب، وهو أن الفعل كما ينسب إلى المباشر له ينسب إلى ما هو سببه ومسهلة، نحو أن يقال: ﴿ٱلرَّحۡمَٰنُ ۝ عَلَّمَ﴾، وإنما علمنا من علمه النبي، وعلم النبي جبريل، وجبريل علمه الله عز وجل- فصح أن ينسب إليه ... قيل؟ نحن إنما أجزنا استعمال ما استعمل فيه تعالى لورود السماع به، ولولا ذلك لنزهناه عن كل وصف يطلق على البشر تفاديا من وهم تشبيه", "en": "Some people have imagined things unworthy of Allah from the words \"coming\" and \"arriving\" that He uses of Himself — here, and in \"Allah came upon them from where they did not expect\", \"Allah came at their building from its foundations\", \"and your Lord comes, and the angels, rank upon rank\". Ar-Raghib gives two causes: too little knowledge of the Creator, and too narrow a grasp of how words are used, literally and figuratively.\n\"Coming\" is not said only of a living body moving from place to place. It is said of setting out with care to do something (\"he came to nobility by its proper door\"), of carrying a task through (\"I came through everything in the book\"), and of an act done through others — as a ruler \"comes\" to a land with his army. A ruler acts sometimes through others and sometimes himself, and in person only in the gravest matters; so when Allah wanted to show a punishment beyond which there is nothing, He ascribed it to Himself as His \"coming\".\nA second way: an act is ascribed both to the one who does it directly and to its first cause. \"The Most Merciful taught the Quran\" — though we learned it from those whom the Prophet ﷺ taught, and the Prophet from Jibril, and Jibril from Allah. So one act is ascribed now to Allah, now to another: \"the angel of death takes you\" and \"Allah takes the souls\".\nAnd his caution: we use such words of Allah only because revelation used them; otherwise we would keep Him above every description used of human beings, lest anyone imagine Him like them.", "ar": "تصوّر بعض الناس ما لا يليق بصفات الله في لفظ المجيء والإتيان الذي وصف به نفسه في هذه الآية، وفي ﴿فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ﴾، و﴿فَأَتَى ٱللَّهُ بُنۡيَٰنَهُم مِّنَ ٱلۡقَوَاعِدِ﴾، و﴿وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا﴾؛ وذلك لأمرين: قصورهم عن معرفة البارئ، وضيق مجالهم في مجاري الألفاظ ومجازها.\nفالإتيان والمجيء لا يُقالان لانتقال الحيّ المتحرّك من مكانٍ إلى مكانٍ فقط، بل يُقالان لقصد القاصد بعنايته أمرًا يستصلحه — «أتيتُ المروءة من بابها» —، ولاستيفاء فعلٍ يتولّاه — «أتيتُ على ما في الكتاب» —، ولفعلٍ يفعله على يد من يستكفيه — كما يُقال: أتى الأمير ناحية كذا بجيشٍ عظيم. ولمّا جرت العادة أن الرئيس يتولّى الأمر بمن يستكفيه تارةً وبنفسه تارةً، ولا يتولّى بنفسه إلا الأعظم، فلمّا أراد الله أن يبيّن العذاب الذي لا غاية وراءه نسبه إلى نفسه إتيانًا له.\nووجهٌ آخر: الفعل كما يُنسب إلى مباشره يُنسب إلى سببه ومسهّله: ﴿ٱلرَّحۡمَٰنُ ۝ عَلَّمَ ٱلۡقُرۡءَانَ﴾، وإنما علّمَنا من علّمه النبيّ، وعلّم النبيَّ جبريل، وجبريلَ علّمه الله؛ ولهذا يُنسب الفعل الواحد تارةً إلى الله وتارةً إلى غيره: ﴿قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ﴾، و﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾.\nقال: وإنما أجزنا استعمال ما استُعمل فيه تعالى لورود السماع به، ولولا ذلك لنزّهناه عن كلّ وصفٍ يُطلق على البشر، تفاديًا من وهم التشبيه.", "links": [{"ref": "42:11", "q": "﴿لَيۡسَ كَمِثۡلِهِۦ شَيۡءٞۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ﴾", "en": "Nothing is like Him", "ar": "ليس كمثله شيء"}, {"ref": "89:22", "q": "﴿وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا﴾", "en": "\"Your Lord comes\"", "ar": "«وجاء ربك»"}, {"ref": "32:11", "q": "﴿قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ﴾", "en": "One act, ascribed to the angel and to Allah", "ar": "فعلٌ واحد يُنسب إلى الملك وإلى الله"}], "v": 1, "p": 434, "pe": 435, "sid": 435},
  {"a": [210, 210], "h": "\"And to Allah all matters return\" — the dominion handed back; souls from the realm of His command", "hAr": "﴿وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ﴾ — المُلك مردود، والأرواح من عالم الأمر", "said": "وقوله: ﴿وَقُضِيَ ٱلۡأَمۡرُۚ﴾ تنبيها أنه حينئذ لا يمكن تلافيه، وأكد ذلك بقوله: ﴿وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ﴾. أي ما قد ملكه عباده في الدنيا من الملك، والملك والتصرف مسترد منهم يوم القيامة، وراجع إليه ... وقيل: عنى بالأمور الأرواح، وسماها أمورا من حيث إنها من الإبداعات المشار إليها بقوله: ﴿إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ﴾، وقوله: ﴿أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ﴾ ... فنبه أن الأرواح كلها مرجوعة إليه وراجعة، كما قال تعالى: ﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾، وعلى ذلك قوله: ﴿كَمَا بَدَأَكُمۡ تَعُودُونَ﴾، ويكون رجوعها إما بربح وغبطة، وإما بندامة وحسرة", "en": "\"And the matter is decided\" — then it cannot be undone. \"And to Allah all matters return\": whatever power, ownership and control His servants were given in this world is taken back on the Day of Resurrection and returns to Him — as one says \"the matter returned to the ruler\" when he takes back what he had delegated.\nAnother reading: \"matters (umur)\" means the souls — called so because they are of the originated realm of His command: \"Our word to a thing, when We will it, is only to say to it 'Be', and it is\"; \"His is the creation and the command\"; and when asked about the spirit: \"the spirit is of my Lord's command\" — of an origination humans cannot picture. All souls are taken back and return to Him — \"as He began you, so you will return\" — some returning with gain and joy, some with regret and sorrow, until He raises them in the second creation.\n\"Shadows of cloud\" may be rain of punishment, like the cloud 'Ad took for rain (\"this is a cloud bringing us rain!\"), or the terrors of the Resurrection.", "ar": "﴿وَقُضِيَ ٱلۡأَمۡرُۚ﴾: تنبيهٌ أنه حينئذٍ لا يمكن تلافيه، وأكّده بـ﴿وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ﴾: ما ملّكه عباده في الدنيا من المِلك والمُلك والتصرّف مستردٌّ منهم يوم القيامة راجعٌ إليه — كما يُقال: رجع الأمر إلى الأمير، أي استردّ ما كان فوّضه.\nوقيل: «الأمور» الأرواح، وسمّاها أمورًا لأنها من الإبداعات المشار إليها بقوله ﴿إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ﴾، و﴿أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ﴾، ولذلك قال لمّا سُئل عن الروح: ﴿قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي﴾ — أي من الإبداع الذي لا يمكن للبشر تصوّره. فنبّه أن الأرواح كلّها مرجوعةٌ إليه راجعة: ﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾، ﴿كَمَا بَدَأَكُمۡ تَعُودُونَ﴾ — ويكون رجوعها إمّا بربحٍ وغبطة، وإمّا بندامةٍ وحسرة، إلى أن ينشئها النشأة الأخرى.\nو﴿ظُلَلٖ مِّنَ ٱلۡغَمَامِ﴾: إشارةٌ إلى أمطار عذاب — كعارض عادٍ: ﴿هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ﴾ —، أو إلى أهوال القيامة.", "links": [{"ref": "40:16", "q": "﴿لِّمَنِ ٱلۡمُلۡكُ ٱلۡيَوۡمَۖ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ﴾", "en": "The dominion handed back", "ar": "المُلك مردودٌ إليه"}, {"ref": "17:85", "q": "﴿قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي﴾", "en": "The spirit, from His command", "ar": "الروح من أمر ربّي"}, {"ref": "46:24", "q": "﴿فَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ﴾", "en": "A cloud of punishment", "ar": "عارض العذاب"}], "v": 1, "p": 435, "pe": 435, "sid": 436},
  {"a": [211, 211], "h": "\"Ask the Children of Israel how many clear signs We gave them\" — a sign is a favour, and changing it is costly", "hAr": "﴿سَلۡ بَنِيٓ إِسۡرَٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةٖۗ﴾ — الآية نعمة، وتبديلها وخيم", "said": "نبه بلفظ (كم) على كثرة ما آتاهم من الآيات، ودل بقوله: ﴿وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ﴾ على إضمار بدلوا، وعلى هذا إن الحكم ليس مقصورا عليهم، بل هو عام فيهم وفي غيرهم، ودل بقوله: ﴿نِعۡمَةَ ٱللَّهِ﴾ أن الآية من جملة نعمته، بل هي من أعظم النعم", "en": "\"How many\" points to how numerous the signs they were given were. \"Whoever changes Allah's favour\" implies \"they changed it\" — and the ruling is not theirs alone: it holds for anyone. And calling the sign \"Allah's favour\" shows that a sign is itself a blessing — indeed among the greatest. \"After it has come to him\" echoes \"after the clear proofs came\" just before. So: whoever exchanges Allah's favour after being singled out for it, Allah punishes severely — as He punished the Children of Israel and all who do as they did.", "ar": "نبّه بلفظ «كم» على كثرة ما آتاهم من الآيات، ودلّ بقوله ﴿وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ﴾ على إضمار «فبدّلوا»، وأن الحكم ليس مقصورًا عليهم بل عامٌّ فيهم وفي غيرهم. ودلّ بقوله ﴿نِعۡمَةَ ٱللَّهِ﴾ على أن الآية من جملة نعمه، بل من أعظم النعم؛ و﴿مِنۢ بَعۡدِ مَا جَآءَتۡهُ﴾ نحو ﴿مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ﴾. فتقديره: آتيناهم آياتٍ هي نعمٌ فبدّلوها، ومن يبدّل نعمة الله بعد اختصاصه بها عاقبه الله عقابًا شديدًا — كما عاقب بني إسرائيل ومن فعل فعلهم.", "links": [{"ref": "14:28", "q": "﴿أَلَمۡ تَرَ إِلَى ٱلَّذِينَ بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرٗا وَأَحَلُّواْ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ﴾", "en": "Exchanging Allah's favour", "ar": "تبديل نعمة الله"}, {"ref": "17:101", "q": "﴿وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ تِسۡعَ ءَايَٰتِۭ بَيِّنَٰتٖۖ﴾", "en": "The many signs", "ar": "الآيات الكثيرة"}], "v": 1, "p": 436, "pe": 436, "sid": 437},
  {"a": [212, 212], "h": "Who made this world attractive — Allah or Satan? An alleged contradiction answered", "hAr": "من زيّن الدنيا — الله أم الشيطان؟ جوابٌ عن دعوى التناقض", "said": "التزيين التحسين المدرك بالحس دون المدرك بالعقل، ولهذا جاء في أوصاف الدنيا دون أوصاف الآخرة ... وجمع بعض الملاحدة بين هذه الآية وأخواتها وزعم أن ذلك من الآيات المتناقضة في القرآن ... ووهي ما ادعاه لا يخفى على ذي بصيرة، لكن بيانه يحتاج إلى مقدمة، فنقول وبالله التوفيق: إن الله- عز وجل خلق الإنسان وجعل له سبيلا إلى بقائه بشخصه زمانا ما، وبنوعه مدة ما، وركب فيه شهوة تشوقه إلى الغذاء والجماع اللذين هما سببا البقاءين، فهذا هو تزيين الله عز وجل- وأمره باستعمالها حسب ما تأمره الشريعة فيها يؤدي به إلى سعادته في الآخرة على ما ينبغي، وبقدر ما ينبغي، ومن عشقها بإفراط، استحوذ الشيطان عليه وأعماه عن قبح المستقبح منه، وذلك قوله تعالى: ﴿وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ﴾ ... فالتزيين في الآيتين يحتمل وجهين أحدهما أن الذي زينه هو المشروع لهم، والثاني: أن الذي زينه هو الشهوة لكن على أن يأخذ بقدر ما يجب، وفي وقت ما يجب، لا أن يجعلها مقصده", "en": "Tazyin, \"making attractive\", is a beauty the senses perceive, not reason — which is why it is used of this world and never of the next.\nAn old critic of Islam gathered the verses and called them contradictory: \"Satan made their deeds attractive to them\"; \"We made attractive to every nation its deeds\" — ascribing it to Allah; \"We assigned them companions who made attractive to them…\". Ar-Raghib: the weakness of the claim is plain to anyone who sees, but it needs a first principle.\nAllah created the human being with a way to survive as a person for a time and as a species for an age, and placed in him the desires for food and for intimacy, the causes of both kinds of survival. That is Allah's \"making attractive\". And He commanded him to use them as the law directs — in the right way and the right measure — which leads him to happiness in the next world. Whoever loves them to excess, Satan takes hold of him and blinds him to the ugliness of what is ugly: that is \"Satan made their deeds attractive\". And \"We made attractive to every nation its deeds\" means either what was prescribed for them, or the desire itself — on condition that it is taken in due measure and at the due time, not made one's goal.\nSo there is no contradiction: the same attraction, placed by Allah for our good, becomes Satan's tool when we make it our aim.", "ar": "«التزيين» التحسين المدرَك بالحسّ دون المدرَك بالعقل، ولهذا جاء في أوصاف الدنيا دون الآخرة: ﴿زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ﴾.\nوجمع بعض الملاحدة بين هذه الآية وأخواتها وزعم أنها متناقضة: قال مرّةً ﴿وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ﴾، ومرّةً ﴿زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ﴾ فنسبه إلى نفسه، ومرّةً ﴿وَقَيَّضۡنَا لَهُمۡ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ﴾. قال الراغب: وَهْيُ ما ادّعاه لا يخفى على ذي بصيرة، لكن بيانه يحتاج إلى مقدّمة:\nخلق الله الإنسان وجعل له سبيلًا إلى بقائه بشخصه زمانًا وبنوعه مدّة، وركّب فيه شهوةً تشوّقه إلى الغذاء والجماع اللذين هما سببا البقاءين — فهذا تزيين الله —، وأمره باستعمالها حسب ما تأمره الشريعة، على ما ينبغي وبقدر ما ينبغي، فيؤدّيه ذلك إلى سعادته في الآخرة؛ ومن عشقها بإفراطٍ استحوذ عليه الشيطان وأعماه عن قبح المستقبح — وذلك ﴿وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ﴾. وأمّا ﴿زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ﴾ و﴿زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ﴾ فيحتمل أن المزيَّن هو المشروع لهم، أو الشهوة على أن تُؤخذ بقدر ما يجب وفي وقت ما يجب، لا أن تُجعل مقصدًا.\nفلا تناقض: الشهوة التي ركّبها الله لمصلحتنا تصير أداةً للشيطان حين نجعلها غايتنا.", "links": [{"ref": "3:14", "q": "﴿زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ﴾", "en": "The attraction placed in people", "ar": "الزينة المركّبة في الناس"}, {"ref": "6:108", "q": "﴿كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ﴾", "en": "\"We made attractive\"", "ar": "«زيّنّا»"}, {"ref": "27:24", "q": "﴿وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ﴾", "en": "\"Satan made attractive\"", "ar": "«وزيّن لهم الشيطان»"}, {"ref": "57:20", "q": "﴿ٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞ وَزِينَةٞ وَتَفَاخُرُۢ بَيۡنَكُمۡ﴾", "en": "What this world is", "ar": "ما الحياة الدنيا"}], "v": 1, "p": 436, "pe": 437, "sid": 437},
  {"a": [212, 212], "h": "\"Allah provides for whom He wills without reckoning\" — wealth is no mark of honour", "hAr": "﴿وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ﴾ — المال ليس علامة كرامة", "said": "وقوله: ﴿وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ﴾ ... السادس: إن ذلك إشارة إلى توسيعه على الكفار والفساق الذين قال فيهم: ﴿وَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ﴾ تنبيها أن لا فضيلة في المال، ولا إكرام لمن يوسع عليه ما لم يستعن به في الوصول إلى المطلوب منه ... السابع: يعطي أولياءه بلا تبعة ولا حساب عليهم فيما يعطون، وذاك أن المؤمن لا يأخذ من عرض الدنيا إلا من حيث يجب، وفي وقت ما يجب وعلى الوجه الذي يجب، ولا ينفقه إلا على ذلك، فهو يحاسب نفسه فلا يحاسب ... وعلى هذا قال لسليمان: ﴿هَٰذَا عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابٖ﴾ أي: تحر فيما أعطيناك الوجه الذي لا تبعة فيه عليك ولا حساب", "en": "The disbelievers mock the believers for their poverty — but \"those who are God-conscious will be above them on the Day of Resurrection\". This world's life is the lowly, near life; the life that truly is life is the next, and only the God-conscious know it.\n\"Without reckoning\" has many meanings — giving more than is deserved; giving without taking back; beyond anyone's counting; without stinting. Two of ar-Raghib's readings stand out. It may point to how widely Allah gives to disbelievers and the corrupt — \"were it not that all people would become one community, We would have given those who disbelieve roofs of silver\" — to show that there is no merit in wealth, and no honour in being given plenty, unless it helps one reach what one was made for: \"do they think that the wealth and sons We give them mean We hasten to them with good?\" As 'Ali said, whoever is given plenty in this world and does not see that he is being tested has been tricked out of his reason.\nOr it may mean He gives His friends without any reckoning against them — because a believer takes from this world only from where he should, when he should and as he should, and spends it only so. He holds himself to account, so he is not held to account — as Sulayman was told: \"this is Our gift; give or withhold, without reckoning\".", "ar": "يسخر الكفّار من المؤمنين لفقرهم، و﴿وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ﴾: فالحياة حياتان: دنيا دنيّة، وأخرى سنيّة هي ﴿ٱلۡحَيَوَانُۚ﴾، ولا يعرفها إلا الذين اتّقوا.\nو﴿بِغَيۡرِ حِسَابٖ﴾ فُسّر على أوجه: يعطيه أكثر ممّا يستحقّ، أو يعطيه ولا يأخذ منه، أو عطاءً لا يحصره عدّ العباد، أو بلا مضايقة. ومن أوجهه عند الراغب: أنه إشارةٌ إلى توسيعه على الكفّار والفسّاق الذين قال فيهم: ﴿وَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ﴾، تنبيهًا على أن لا فضيلة في المال، ولا إكرام لمن وُسّع عليه ما لم يستعن به في الوصول إلى المطلوب منه: ﴿أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ ۝ نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ﴾؛ وقال عليٌّ: «من وُسّع عليه في دنياه فلم يعلم أنه مُكر به فقد خُدع عن عقله».\nومنها: أنه يعطي أولياءه بلا تبعةٍ ولا حسابٍ عليهم فيما يُعطَون، لأن المؤمن لا يأخذ من عرض الدنيا إلا من حيث يجب، وفي وقت ما يجب، وعلى الوجه الذي يجب، ولا ينفقه إلا كذلك؛ فهو يحاسب نفسه فلا يُحاسَب؛ وعلى هذا قال لسليمان: ﴿هَٰذَا عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابٖ﴾.", "links": [{"ref": "43:33", "q": "﴿وَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ﴾", "en": "Wealth given even to those who reject Him", "ar": "المال يُعطى حتى للكافرين"}, {"ref": "23:55-56", "q": "﴿أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ ۝ نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ﴾", "en": "Plenty is not proof of favour", "ar": "الكثرة ليست دليل رضا"}, {"ref": "38:39", "q": "﴿هَٰذَا عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابٖ﴾", "en": "Given without reckoning", "ar": "عطاءٌ بغير حساب"}, {"ref": "40:40", "q": "﴿فَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ يُرۡزَقُونَ فِيهَا بِغَيۡرِ حِسَابٖ﴾", "en": "Provision without reckoning in Paradise", "ar": "رزقٌ بغير حساب في الجنّة"}], "v": 1, "p": 438, "pe": 439, "sid": 439},
  {"a": [213, 213], "h": "\"People were one nation\" — in faith, or in disbelief? Both, at different times", "hAr": "﴿كَانَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ﴾ — في الإيمان أم في الكفر؟ كلاهما في طورين", "said": "وهي أن الله - عز وجل - فطر الناس فطرة ركز فيها روية يعرف بها بعض الأشياء اضطرارا، ومكنه أن يعرف بها البعض اكتسابا ... ولم يخلهم في وقت من نبي يشحذ عقولهم ويعرفهم ما لا سبيل لهم إلى معرفته من دونه، وكان كلما تختل أحوالهم بعد خروج نبيهم من بينهم، إما أن يقيض لهم من يجدد عليهم شريعتهم السالفة، أو يبعث إليهم نبيا يأتيهم بشريعة مستأنفة، وهذا كان فعله إلى أن ينتهي الأمر إلى نبينا - عليه السلام -، فختم به الأنبياء، فمن قالوا: كانوا أمة في الإيمان، فنظر منه إلى المبدأ وحال الفطرة وما كانوا عليه قبل أن فسدوا، ومن قالوا: كانوا أمة واحدة في الكفر، فنظر منه إلى حين فسادهم، كما بين زمن بعثة نوح وبعثة إبراهيم - عليهما السلام، وكل واحد من القولين صحيح بنظر ونظر، فقد كانوا أمة واحدة في الإيمان طورا، وأمة واحدة في الكفر طورا", "en": "Ibn 'Abbas, Ubayy and as-Suddi said people were one nation in faith; others said in disbelief. Ar-Raghib shows the two are views from two moments.\nAllah made people with a natural disposition in which He planted a power of reflection: by it they know some things necessarily and can come to know others; He made them love true belief over false, beautiful deeds over ugly, and true speech over lies — \"the fitrah of Allah\", \"the dye of Allah\", the covenant with the children of Adam, \"every child is born upon the fitrah\". And He never left them, at any time, without a prophet to sharpen their minds and teach them what they could not know without him. Whenever their state decayed after their prophet had gone, He either raised someone to renew their earlier law, or sent a prophet with a new law — until it reached our Prophet ﷺ, with whom the prophets were sealed.\nThose who said \"one nation in faith\" were looking at the beginning — the fitrah, before corruption; those who said \"in disbelief\" were looking at the times of corruption, such as the age between Nuh and Ibrahim. Both are right: at one stage they were one nation in faith, at another one nation in disbelief. (And if the earth is never without someone who stands for Allah's truth, in such times so few listened to him that he did not change what the nation was.)", "ar": "قال ابن عباس وأُبيّ والسدّي: كانوا أمّةً واحدةً في الإيمان؛ وقال غيرهم: في الكفر. وهذا الخلاف لاختلاف نظرين، ولا بدّ له من مقدّمة:\nفطر الله الناس فطرةً ركز فيها رويّةً يعرفون بها بعض الأشياء اضطرارًا، ومكّنهم أن يعرفوا بها بعضها اكتسابًا، وحبّب إليهم الحقّ من الاعتقاد دون الباطل، والجميل من الفعال دون القبيح، والصدق من المقال دون الكذب: ﴿فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ﴾، ﴿صِبۡغَةَ ٱللَّهِ﴾، ﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾، «كلّ مولودٍ يولد على الفطرة». ولم يُخلِهم في وقتٍ من نبيٍّ يشحذ عقولهم ويعرّفهم ما لا سبيل لهم إلى معرفته من دونه؛ وكلّما اختلّت أحوالهم بعد خروج نبيّهم من بينهم قيّض لهم من يجدّد شريعتهم السالفة، أو بعث نبيًّا بشريعةٍ مستأنفة — إلى أن انتهى الأمر إلى نبيّنا ﷺ فخُتم به الأنبياء.\nفمن قال «أمّةً في الإيمان» نظر إلى المبدأ وحال الفطرة قبل أن يفسدوا، ومن قال «في الكفر» نظر إلى حين فسادهم — كما بين نوحٍ وإبراهيم —؛ وكلا القولين صحيحٌ بنظر: فقد كانوا أمّةً واحدةً في الإيمان طورًا، وفي الكفر طورًا. (فإن قيل: الأرض لا تخلو من حجّةٍ لله؟ قيل: من كان حجّةً في مثل ذلك الوقت لم يُعتدّ به في كونهم أمّةً لقلّة الإصغاء إليه.)", "links": [{"ref": "10:19", "q": "﴿وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةٗ وَٰحِدَةٗ فَٱخۡتَلَفُواْۚ﴾", "en": "The same words in Yunus", "ar": "الكلمات نفسها في يونس"}, {"ref": "30:30", "q": "﴿فَأَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ﴾", "en": "The fitrah they began with", "ar": "الفطرة التي بدؤوا عليها"}, {"ref": "33:40", "q": "﴿مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٖ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ﴾", "en": "The prophets sealed", "ar": "خاتم النبيين"}], "v": 1, "p": 440, "pe": 441, "sid": 441},
  {"a": [213, 213], "h": "\"Allah guides whom He wills\" — guidance is everywhere, but few see it, like the stars", "hAr": "﴿وَٱللَّهُ يَهۡدِي مَن يَشَآءُ﴾ — الهدى كثيرٌ وقليلٌ من يراه، كالنجوم", "said": "قيل إن من كان حجة الله - عز وجل - في مثل ذلك الوقت في حكم من لا اعتداد به في كونهم أمة لقلة الإصغاء إليه ... إن قيل: كيف قال: ﴿وَٱللَّهُ يَهۡدِي مَن يَشَآءُ﴾، وذلك يقتضي أنه هدى بعضا دون بعض، وحق جوده وكرمه أن يعمهم بالهدى؟ قيل: إنه قد عمهم من حيث قد أباحه لهم وقيضه، لكن لم يهتد به الكل، فإن هدايته لا يدركها إلا من جلى بصيرته، وشحذ فهمه ليعرفه، فيهتدي به، وقد قال بعض الصالحين: ما أكثر الهدى وأقل من يرى، ألا ترى أن نجوم المساء ما أكثرها، ولا يهتدي بها إلا العلماء؟", "en": "Allah sent prophets \"bringing good news and warning\" — good news to those who do good, warning to those who do evil — and gave every prophet a book to guide him and his people, either his own or the book of an earlier prophet he was told to follow (as the prophets among the tribes of Israel followed the Torah). Then people disagreed — \"only those who were given it disagreed, after clear proofs came, out of rivalry among themselves\": blamed, because clear proofs are meant to end disagreement; and the cause was rivalry — wanting this world's glitter and rank.\n\"Allah guides whom He wills\": does His generosity not require guiding everyone? Ar-Raghib: it did reach everyone — He made guidance available to all and set it within their reach — but not all were guided by it; for His guidance is perceived only by one who polishes his inner sight and sharpens his understanding in order to know it. As a righteous man said: \"How plentiful guidance is, and how few see it! Look how many stars there are in the evening sky — yet only those who know are guided by them.\"", "ar": "بعث الله أنبياءه مبشّرين للمحسنين ومنذرين للمسيئين، ولم يُخلِ أحدًا منهم من كتابٍ يرشده ويرشدهم: إمّا كتابٍ خُصّ به، وإمّا كتابِ من قبله أُمر بالاعتماد عليه — كالأسباط الذين كانوا أنبياء وكتابهم التوراة. ثم ﴿وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ﴾: ذمٌّ للمختلفين، فمن شأن البيّنات أن ترفع الخلاف؛ وسببه البغي — طلبهم زخرف الدنيا ومنازلها.\nفإن قيل: ﴿وَٱللَّهُ يَهۡدِي مَن يَشَآءُ﴾ يقتضي أنه هدى بعضًا دون بعض، وحقّ جوده أن يعمّهم؟ قيل: قد عمّهم من حيث أباحه لهم وقيّضه، لكن لم يهتدِ به الكلّ، فهدايته لا يدركها إلا من جلا بصيرته وشحذ فهمه ليعرفه فيهتدي به. وقد قال بعض الصالحين: «ما أكثر الهدى وأقلّ من يرى! ألا ترى أن نجوم المساء ما أكثرها، ولا يهتدي بها إلا العلماء؟»", "links": [{"ref": "16:16", "q": "﴿وَعَلَٰمَٰتٖۚ وَبِٱلنَّجۡمِ هُمۡ يَهۡتَدُونَ﴾", "en": "Guided by the stars — those who know", "ar": "يهتدون بالنجم"}, {"ref": "10:93", "q": "﴿فَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ﴾", "en": "Disagreement after knowledge came", "ar": "اختلفوا بعد مجيء العلم"}, {"ref": "3:105", "q": "﴿وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ﴾", "en": "A warning to this nation", "ar": "تحذير هذه الأمّة"}], "v": 1, "p": 441, "pe": 442, "sid": 442},
  {"a": [214, 214], "h": "\"Did you think you would enter Paradise without being tried?\" — no honey without the bees' stings", "hAr": "﴿أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ﴾ — لا بدّ دون الشهد من إبر النحل", "said": "بين تعالى أنه لا سبيل للناس كافة إلى الجنة إلا بتحمل المشاق ... قال عليه السلام: \" حفت الجنة بالمكاره، وحفت النار بالشهوات \"، فخاطب هذه الأمة بأنه محال أن ترجو تحصيل الجنة إلا بما جرى به حكم الله في الذين سلفوا، وهو أن تنالكم البأساء أي الفقر، والضراء أي المصائب، والزلزلة أي المخاوف، وبذلك أثنى على المؤمنين فقال: ﴿وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ﴾ وليس ذلك في الأمور الإلهية فقط، بل في عامة الملاذ لا سبيل إلى منحة إلا بمحنة، ولا إلى لذة إلا بشدة. ولهذا قيل: ولا بد دون الشهد من إبر النحل", "en": "Zalzalah, \"being shaken\", is violent motion; the root zall (\"slip\") is doubled to double the meaning, as dall becomes daldal.\nThere is no way to Paradise for anyone except by bearing hardship — \"Paradise is surrounded by what the soul dislikes, and the Fire by its desires\". So this nation is told: you cannot hope to reach Paradise except by the way Allah's decree ran for those before you — poverty, calamity, and fear; and it is for exactly this that the believers were praised: \"the patient in poverty, illness and the time of battle — those are the truthful\".\nAnd this is not only so in matters of religion: in every pleasure of life, there is no gift without a trial and no delight without hardship — as the poet said, \"there is no honey without the stings of the bees\".\n\"Until the Messenger and those who believed with him said: when will Allah's help come?\" — as if it were slow; then they recovered their certainty: \"surely Allah's help is near\". (Or: the followers asked \"when?\", and the Messenger answered \"surely it is near\" — the two sayings joined.)", "ar": "«الزلزلة» شدّة الحركة، وأصلها «زلّ»، زِيد لفظه لزيادة معناه، كـ«دلّ» و«دلدل».\nبيّن تعالى أنه لا سبيل للناس كافّةً إلى الجنّة إلا بتحمّل المشاقّ، ولهذا قال ﷺ: «حُفّت الجنّة بالمكاره، وحُفّت النار بالشهوات». فخاطب هذه الأمّة بأنه محالٌ أن ترجو الجنّة إلا بما جرى به حكم الله في الذين سلفوا: أن تنالكم البأساء — الفقر —، والضرّاء — المصائب —، والزلزلة — المخاوف؛ وبذلك أثنى على المؤمنين: ﴿وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ﴾.\nوليس ذلك في الأمور الإلهيّة فقط، بل في عامّة الملاذّ: لا سبيل إلى منحةٍ إلا بمحنة، ولا إلى لذّةٍ إلا بشدّة؛ ولهذا قيل: «ولا بدّ دون الشهد من إبر النحل».\nو﴿حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ﴾: قيل: قالوها استبطاءً، ثم تداركوا وعادوا إلى معرفتهم فقالوا ﴿أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ﴾؛ وقيل: قال الأتباع «متى نصر الله»، وقال الرسول «ألا إن نصر الله قريب»، فجمع بين قوليهما.", "links": [{"ref": "3:142", "q": "﴿أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّٰبِرِينَ﴾", "en": "The same question in Al 'Imran", "ar": "السؤال نفسه في آل عمران"}, {"ref": "2:177", "q": "﴿وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ﴾", "en": "The patience it calls for", "ar": "الصبر المطلوب"}, {"ref": "94:5", "q": "﴿فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا﴾", "en": "Ease comes with hardship", "ar": "مع العسر يسر"}], "v": 1, "p": 442, "pe": 443, "sid": 443},
  {"a": [215, 215], "h": "\"They ask what they should spend\" — and are told on whom: a teacher answers like a physician", "hAr": "﴿يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ﴾ — فأُجيبوا بمن يُنفَق عليه: المعلّم يجيب كالطبيب", "said": "إن قيل: ليس جوابهم طبقة لسؤالهم فإن سؤالهم عما ينفق، والجواب عمن ينفق عليه قيل: في ذلك جوابان، أحدهما أنهم سألوا عنهما وقالوا: ما ينفق؟ وعلى من ينفق؟ ولكن حذف في حكاية السؤال أحدهما إيجازا، ودل عليه الجواب بقوله: ﴿مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ﴾، كأنه قيل: المنفق هو الخير، والمنفق عليهم هؤلاء، فلف أحد الجوابين في الآخر، وهذا طريق معروف في البلاغة، والجواب الثاني أن السؤال ضربان سؤال جدل وحقه أن يطابقه جوابه لا زائدا عليه ولا ناقصا عنه، وسؤال تعلم، وحق المعلم أن يصير فيه كطبيب دقيق يتحرى شفاء سقيم، فيطلب ما يشفيه طلبه المريض، أو لم يطلبه فلما كان حاجتهم إلى من ينفق عليهم كحاجتهم إلى ما ينفق بين لهم الأمرين ... وقوله: ﴿مِّنۡ خَيۡرٖ﴾ أي من مال، فسمي المال خيرا تنبيها أن الذي يجوز إنفاقه هو الحلال الذي يتناوله اسم الخير، كما قال: ﴿إِن تَرَكَ خَيۡرًا﴾", "en": "They asked what to spend, and the answer tells them on whom. Does the answer miss the question? Ar-Raghib gives two answers. They may have asked both — what, and on whom — and the report kept one question for brevity, while the answer covers both: \"whatever good you spend\" (what: good) \"is for parents, relatives, orphans, the needy and the traveller\" (on whom) — one answer folded inside the other, a well-known device of eloquence.\nAnd the deeper answer: there are two kinds of question. A question in debate should be answered exactly — no more, no less. But a question asked in order to learn is different: the teacher should be like a careful physician who seeks the patient's cure, and gives what will heal him whether or not he asked for it. Their need to know whom to give to was as great as their need to know what to give, so they were taught both.\nThe recipients named are examples, not a complete list; and parents and relatives are named first to show their right is binding. \"Of good\" means of wealth — called \"good\" to show that only lawful wealth, worthy of the name, may be given. \"And whatever good you do, Allah knows it\" — and will repay it: \"whoever does an atom's weight of good will see it\".", "ar": "فإن قيل: ليس الجواب طِبق السؤال، فقد سألوا عمّا يُنفَق، وأُجيبوا عمّن يُنفَق عليه؟ قيل جوابان: أنهم سألوا عنهما — ما ننفق؟ وعلى من ننفق؟ — فحُذف أحدهما في حكاية السؤال إيجازًا، ودلّ عليه الجواب: ﴿مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ﴾ — المُنفَق هو الخير، والمُنفَق عليهم هؤلاء —، فلُفّ أحد الجوابين في الآخر، وهذا طريقٌ معروفٌ في البلاغة.\nوالثاني: أن السؤال ضربان: سؤال جدل، وحقّه أن يطابقه جوابه لا زائدًا ولا ناقصًا؛ وسؤال تعلّم، وحقّ المعلّم فيه أن يكون كطبيبٍ دقيقٍ يتحرّى شفاء سقيم، فيعطيه ما يشفيه طلبه المريض أو لم يطلبه؛ فلمّا كانت حاجتهم إلى معرفة من يُنفَق عليه كحاجتهم إلى معرفة ما يُنفَق، بيّن لهم الأمرين.\nوذكر من ذكر مثالًا لا حصرًا، وقدّم الوالدين والأقربين تنبيهًا على وجوب حقّهم. و﴿مِّنۡ خَيۡرٖ﴾: من مال، وسمّى المال خيرًا تنبيهًا أن الذي يجوز إنفاقه هو الحلال الذي يتناوله اسم الخير، كقوله ﴿إِن تَرَكَ خَيۡرًا﴾. ثم ﴿وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ﴾ — تنبيهًا أنه يُجازى به: ﴿فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ﴾.", "links": [{"ref": "2:219", "q": "﴿وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ﴾", "en": "The same question a few verses on — a different answer", "ar": "السؤال نفسه بعد آيات بجوابٍ آخر"}, {"ref": "9:60", "q": "﴿إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ﴾", "en": "Those with a fixed share", "ar": "أصحاب الحقّ المعلوم"}, {"ref": "99:7", "q": "﴿فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ﴾", "en": "Every good repaid", "ar": "كلّ خيرٍ مجزيّ"}], "v": 1, "p": 444, "pe": 444, "sid": 445},
  {"a": [216, 216], "h": "\"Fighting is prescribed for you, though you dislike it\" — why our likes and dislikes are not the measure", "hAr": "﴿كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ﴾ — لماذا لا تكون محبّتنا وكراهتنا هي الميزان", "said": "الكره في الإنسان يستعمل على ضربين، أحدهما ما يعاف من حيث الطبع، والثاني ما يعاف من حيث العقل وإن مال إليه الطبع، ولهذا يصح أن يوصف الشيء بأنه مراد مكروه ... ونبه بقوله: ﴿وَعَسَىٰٓ أَن تَكۡرَهُواْ﴾ بألطف وجه على أن ما كتب عليهم من القتال خير لهم بأوضح الأدلة وهي أنه إذا جاز أن يكون منكم كراهية لأمر وفيه الخير، فيجوز أن يكون كراهتكم لما كتب عليكم من القتال كذلك، وإذا جاز أن تحبوا شيئا وهو شر لكم، فيجوز أن تكون محبتكم لما أحببتموه شرا، ثم نبه أن هذا الجائز كونه عندكم هو واجب كونه في نفسه بقوله: ﴿وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ﴾ أي إذا كان الله - عز وجل - يعلم وأنتم لا تعلمون، وقد قضي بأن ذلك خيرا، فإنما قضي به لأنه خير، وإذا كان خيرا فيجب أن تحبوه، ولا تكرهوه، فالخير يجب إرادته، والشر يجب كراهته، وعلى نحوه دل قوله تعالى: ﴿فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا﴾", "en": "Karh, dislike, is of two kinds: what a person's nature shrinks from, and what reason rejects even when nature leans toward it — which is why one and the same thing can be both wanted and disliked. (His al-Mufradat puts it so: \"I want it by nature and dislike it by reason or by the law — or want it by reason or the law and dislike it by nature.\") Fighting is disliked by nature. In its plain sense the fighting prescribed is fighting the disbelievers; some said it takes in striving against one's own desires as well.\nThen, in the gentlest way, He shows that the fighting prescribed for them is good for them, by the clearest of proofs: if you can dislike something that holds good for you, your dislike of this fighting may be of that kind; and if you can love something that is bad for you, what you love may be bad. Then \"Allah knows and you do not know\" turns this \"may be\" into \"is\": since Allah knows and you do not, and He has decreed it as good, He decreed it only because it is good — and what is good should be loved, not disliked. Good ought to be willed, and evil ought to be disliked.\nThe same is taught by \"it may be that you dislike a thing and Allah places much good in it\". And as the poet said: in some hardships Allah decrees right guidance for a young man, and in some of what he desires lies what he should fear.", "ar": "«الكُره» في الإنسان على ضربين: ما يُعاف من حيث الطبع، وما يُعاف من حيث العقل وإن مال إليه الطبع؛ ولهذا يصحّ أن يوصف الشيء الواحد بأنه مرادٌ مكروه. وفي «المفردات»: «أريده من حيث الطبع وأكرهه من حيث العقل أو الشرع، أو أريده من حيث العقل أو الشرع وأكرهه من حيث الطبع». والقتال مكروهٌ من حيث الطبع. والقتال المكتوب في الظاهر مجاهدة الكفّار، وقيل: عُني معه مجاهدة النفس في الشهوة.\nونبّه بقوله ﴿وَعَسَىٰٓ أَن تَكۡرَهُواْ﴾ بألطف وجهٍ على أن ما كُتب عليهم من القتال خيرٌ لهم، بأوضح الأدلّة: إذا جاز أن تكرهوا أمرًا فيه الخير، جاز أن تكون كراهتكم لما كُتب عليكم من القتال كذلك؛ وإذا جاز أن تحبّوا شيئًا وهو شرٌّ لكم، جاز أن يكون ما أحببتموه شرًّا. ثم نبّه بقوله ﴿وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ﴾ أن هذا الجائز عندكم واجبٌ في نفسه: فإذا كان الله يعلم وأنتم لا تعلمون، وقد قضى بأنه خير، فإنما قضى به لأنه خير؛ وإذا كان خيرًا وجب أن تحبّوه ولا تكرهوه — فالخير تجب إرادته، والشرّ تجب كراهته.\nوعلى نحوه دلّ ﴿فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا﴾؛ وإيّاه قصد الشاعر: «قضى الله في بعض المكاره للفتى * برشدٍ، وفي بعض الهوى ما يُحاذَر».", "links": [{"ref": "4:19", "q": "﴿فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا﴾", "en": "The same rule, said of marriage", "ar": "القاعدة نفسها في الزواج"}, {"ref": "22:39", "q": "﴿أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ﴾", "en": "Why fighting was permitted: they had been wronged", "ar": "لماذا أُذن بالقتال: لأنهم ظُلموا"}, {"ref": "2:190", "q": "﴿وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ﴾", "en": "Whom to fight, and the limit not to cross", "ar": "من يُقاتَل، والحدّ الذي لا يُتجاوز"}], "v": 1, "p": 445, "pe": 445, "sid": 446},
  {"a": [217, 217], "h": "\"Fighting in the sacred month is grave\" — but not every fighting in it; graver is barring people from Allah's way", "hAr": "﴿قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ﴾ — لا كلّ قتالٍ فيه، وأكبر منه الصدّ عن سبيل الله", "said": "والسائل على ذلك قيل أهل الشرك قصدا إلى تعيير المسلمين مما استجازوه من القتل في الشهر الحرام وقيل: هم أهل الإسلام ... إن قيل: لم لم يقل: القتال فيه كبير ... قيل: في ذكره منكرا تنبيه أن ليس كل القتال في الشهر الحرام هذا حكمه، فإن قتال النبي- عليه السلام- لأهل مكة لم يكن هذا حكمه ... ﴿وَصَدٌّ عَن سَبِيلِ ٱللَّهِ﴾ تنبيه أنه على الوجه الذي يفعله الكفار صد عن سبيل الله، أي عن دينه وعن نبيه، وأكثر منه عند الله وأعظم إخراج أهل المسجد ... وعلى ذلك دل بقوله لهم: ﴿وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ﴾ ... ثم بين أن النبي- عليه السلام- وأمته هم أولياؤه بقوله: ﴿إِنۡ أَوۡلِيَآؤُهُۥٓ إِلَّا ٱلۡمُتَّقُونَ﴾، وفي ذلك تنبيه أن قتال المسلمين وقتلهم فيه ليس بكبير", "en": "Who asked? Some say the idolaters, wanting to shame the Muslims for having allowed themselves to kill in a sacred month; some say the Muslims themselves.\nWhy \"fighting in it is grave\" — \"fighting\" without \"the\"? Because a noun repeated in Arabic normally comes back with \"the\"; leaving it without shows that not all fighting in the sacred month is judged so. The Prophet's ﷺ fighting against the people of Makkah was not — \"it was made lawful for me for one hour of a day\".\n\"Barring from Allah's way\", done as the disbelievers do it, is barring people from His religion and His Prophet; and greater still in Allah's sight is driving out the people of the Sacred Mosque — the believers, its true guardians: \"Why should Allah not punish them, when they bar people from the Sacred Mosque and they are not its guardians? Its guardians are only the God-conscious\" — the Prophet ﷺ and his nation. So, he says, the Muslims' fighting in it was not the grave thing. And \"persecution is worse than killing\" was explained at 2:191.", "ar": "والسائل قيل: أهل الشرك، قصدًا إلى تعيير المسلمين بما استجازوه من القتل في الشهر الحرام؛ وقيل: أهل الإسلام.\nفإن قيل: لِمَ لم يقل «القتال فيه كبير»، والنكرة إذا أُعيد ذكرها أُعيدت معرّفة؟ قيل: في ذكره منكّرًا تنبيهٌ أن ليس كلّ القتال في الشهر الحرام هذا حكمه، فقتال النبيّ ﷺ لأهل مكّة لم يكن هذا حكمه، وقد قال: «أُحلّت لي ساعةً من نهار».\nو﴿وَصَدٌّ عَن سَبِيلِ ٱللَّهِ﴾: تنبيهٌ أنه — على الوجه الذي يفعله الكفّار — صدٌّ عن دين الله وعن نبيّه، وأكبر منه عند الله إخراج أهل المسجد: المؤمنين الذين هم أولياؤه، كما قال: ﴿وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ﴾، ثم بيّن أن النبيّ ﷺ وأمّته هم أولياؤه: ﴿إِنۡ أَوۡلِيَآؤُهُۥٓ إِلَّا ٱلۡمُتَّقُونَ﴾. وفي ذلك تنبيهٌ أن قتال المسلمين فيه ليس بالكبير. و﴿وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ﴾ تقدّم الكلام فيه عند الآية ١٩١.", "links": [{"ref": "8:34", "q": "﴿وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾", "en": "Who the Sacred Mosque's guardians are", "ar": "من أولياء المسجد الحرام"}, {"ref": "2:191", "q": "﴿وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ﴾", "en": "\"Persecution is worse than killing\" — the first time", "ar": "«والفتنة أشد من القتل» — أوّل مرّة"}, {"ref": "9:36", "q": "﴿إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرٗا﴾", "en": "The four sacred months", "ar": "الأشهر الحرم الأربعة"}], "v": 1, "p": 446, "pe": 447, "sid": 447},
  {"a": [217, 217], "h": "\"They will not stop fighting you until they turn you from your religion — if they can\": and they cannot", "hAr": "﴿وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ﴾ — ولن يستطيعوا", "said": "والحبط فساد يلحق الماشية في بطونها من أكل الكلأ، واستعير لفساد العمل ... ونبه بقوله: ﴿إِنِ ٱسۡتَطَٰعُواْۚ﴾ أنهم لا يردونكم، لأنهم لا يستطيعون، وذلك نحو قوله: ﴿وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ﴾ وعقب ذلك بوعيد من يرتد، فمات على حالته، وإن أعماله المتقدمة المعمولة في سبب الدنيا والآخرة تبطل وتضمحل كما قال: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾", "en": "Nothing will satisfy them, he says, but your leaving your faith: \"they will not stop fighting you until they turn you back from your religion\". And \"if they can\" tells you that they will not turn you back, because they cannot — like \"the Jews and the Christians will not be pleased with you until you follow their way\" (2:120).\nThen comes the warning to whoever turns back and dies in that state: all his earlier deeds come to nothing and vanish, in this world and the next — \"We will turn to the deeds they did and make them scattered dust\". Habt, \"coming to nothing\", is first a sickness that strikes cattle in their bellies from a pasture they ate; it was borrowed for deeds that go bad.", "ar": "لا يرضيهم إلا ارتدادكم: ﴿وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ﴾؛ ونبّه بقوله ﴿إِنِ ٱسۡتَطَٰعُواْۚ﴾ أنهم لا يردّونكم لأنهم لا يستطيعون، وذلك نحو قوله ﴿وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ﴾.\nوعقّب ذلك بوعيد من يرتدّ فيموت على حاله: أن أعماله المتقدّمة تبطل وتضمحلّ في الدنيا والآخرة، كما قال: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾. و«الحَبَط» فسادٌ يلحق الماشية في بطونها من أكل الكلأ، واستُعير لفساد العمل.", "links": [{"ref": "2:120", "q": "﴿وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ﴾", "en": "The same resolve, named earlier", "ar": "الإصرار نفسه، ذُكر قبلُ"}, {"ref": "25:23", "q": "﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾", "en": "Deeds turned to dust", "ar": "أعمالٌ تصير هباءً"}, {"ref": "5:54", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ﴾", "en": "Whoever turns back — Allah brings others", "ar": "من يرتدّ يأتِ الله بقومٍ غيره"}], "v": 1, "p": 446, "pe": 447, "sid": 447},
  {"a": [218, 218], "h": "\"Those who believed, emigrated and strove hope for Allah's mercy\" — three stations, and hope that is earned", "hAr": "﴿أُوْلَٰٓئِكَ يَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ﴾ — ثلاث منازل، ورجاءٌ مستحقّ", "said": "فمن المفسرين من حمل المهاجرة على مهاجرة الأهل والولد، كهجرة النبي- عليه السلام- وأصحابه والمجاهدة على الغزو، ومنهم من قال: عنى ذلك هجران الشهوات، ومجاهدة الهوى ... وقال في حجة الوداع: (المجاهد من جاهد نفسه في طاعة الله، المهاجر من هجر الخطايا) وهذه المنازل الثلاث التي هي الإيمان والمهاجرة والجهاد هي المعنية بقوله: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ﴾ ولا سبيل إلي المهاجرة إلا بعد الإيمان، ولا إلى الجهاد في سبيله إلا بعد هجران الشهوات، ومن وصل إلي ذلك فحق له أن يرجو رحمته، إن قيل: الإنسان راج لرحمة الله وإن لم يبلغ هذه المنازل، قيل: إن الذي نسميه رجاء لمن لم يبلغ مثل هذه المنازل، فهو تمن على الله ... وما ذكره الله- عز وجل- هاهنا هو الرجاء المستحق الذي وصف به المؤمنين في غير موضع نحو قوله: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾ ... إن قيل: لم ذكر المؤمنين برجاء الرحمة وهي لهم لا محالة؟ قيل: المؤمن وإن بذل الجهد في طاعته، فواجب أن يكون بين نظرين، نظر إلى سعة رحمة الله عز وجل، ونظر إلى ما عسى أن يقع أو وقع منه من ذنب فينتج له خوفا", "en": "Hijrah is leaving another — with the body, or by forgetting him and leaving him in the heart. Jihad is bearing hardship: meeting an enemy with all one's effort. Raja', hope, is named from the \"edge\" of a well: hope stands at the edge, between expectation and despair.\nHaving made the duties of the sacred month and the Sacred Mosque clear, He points to the merit of those who emigrate and strive in His way to guard them. Some commentators take the emigration as leaving home and family, as the Prophet ﷺ and his Companions did, and the striving as going out to fight; others take it as leaving one's desires and striving against one's whims — as the Prophet ﷺ said in the Farewell Pilgrimage: \"the one who strives is he who strives against himself in obeying Allah, and the emigrant is he who leaves sins\". (He also cites the famous \"greater jihad\" report; the hadith scholars judged it weak, and the authentic words just quoted carry its meaning.)\nThese three stations — faith, emigration, striving — are those meant in \"O you who believe, be mindful of Allah, seek the means of nearness to Him, and strive in His way\". There is no emigration except after faith, and no striving in His way except after leaving one's desires; whoever reaches that has the right to hope for His mercy.\nBut does not everyone hope for Allah's mercy, even without these stations? What we call hope in one who has not reached them is only wishful thinking about Allah, or hope for a favour not earned. What Allah names here is earned hope, with which He describes the believers elsewhere: \"they hope for His mercy and fear His punishment\".\nAnd why say the believers \"hope\" for a mercy that is surely theirs? Because a believer, however hard he works at obeying, must stand between two views: one on the vastness of Allah's mercy, and one on the sin he may have done or may yet do — and that brings fear.", "ar": "«الهجر» مفارقة الإنسان غيره، إمّا بالبدن، وإمّا باللسان والقلب. و«الجهد» تحمّل المشقّة، ومجاهدة العدوّ مقاومته ببذل الجهد. و«الرجاء» من «الرَّجا» وهو الناحية: الوقوف على ناحية الأمل، مترددًا بين الأمل واليأس.\nلمّا بيّن وجوب المقاتلة ونهى عن تضييع الشهر الحرام والمسجد الحرام، نبّه على فضل من هاجر وجاهد في سبيل الله محافظةً على ذلك. فمن المفسّرين من حمل المهاجرة على مهاجرة الأهل والولد — كهجرة النبيّ ﷺ وأصحابه — والمجاهدة على الغزو؛ ومنهم من قال: عُني بذلك هجران الشهوات ومجاهدة الهوى، وقد قال ﷺ في حجّة الوداع: «المجاهد من جاهد نفسه في طاعة الله، والمهاجر من هجر الخطايا». (ويذكر الراغب هنا أيضًا رواية «الجهاد الأكبر» المشهورة، وقد ضعّفها أهل الحديث، ويغني عنها الحديث الصحيح الذي قبلها.)\nوهذه المنازل الثلاث — الإيمان والمهاجرة والجهاد — هي المعنيّة بقوله ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ﴾؛ ولا سبيل إلى المهاجرة إلا بعد الإيمان، ولا إلى الجهاد في سبيله إلا بعد هجران الشهوات، ومن وصل إلى ذلك فحقٌّ له أن يرجو رحمته.\nفإن قيل: الإنسان يرجو رحمة الله وإن لم يبلغ هذه المنازل؟ قيل: ما نسمّيه رجاءً ممّن لم يبلغها فهو تمنٍّ على الله، أو رجاءٌ لتفضّلٍ غير مستحقّ؛ وما ذكره الله هنا هو الرجاء المستحقّ الذي وصف به المؤمنين في غير موضع: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾.\nفإن قيل: لِمَ وصف المؤمنين برجاء الرحمة وهي لهم لا محالة؟ قيل: المؤمن وإن بذل الجهد في طاعته فواجبٌ أن يكون بين نظرين: نظرٍ إلى سعة رحمة الله، ونظرٍ إلى ما عسى أن يقع أو وقع منه من ذنب، فيُنتج له خوفًا.", "links": [{"ref": "5:35", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ﴾", "en": "The three stations in one verse", "ar": "المنازل الثلاث في آية"}, {"ref": "17:57", "q": "﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾", "en": "Hope and fear together", "ar": "الرجاء والخوف معًا"}, {"ref": "29:69", "q": "﴿وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ﴾", "en": "Striving opens the ways", "ar": "المجاهدة تفتح السُّبُل"}], "v": 1, "p": 448, "pe": 449, "sid": 449},
  {"a": [219, 219], "h": "\"In them is great sin, and some benefit\" — how wine was forbidden step by step, and why reason agrees", "hAr": "﴿قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ﴾ — كيف حُرّمت الخمر بالتدريج، ولماذا يوافق العقل", "said": "وأشار الله- عز وجل- بقوله: ﴿وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ﴾ إلى تحريمه إشارة لطيفة تحتاج في كشفها إلى مقدمة، وهي أن النفع ضربان، ديني ودنيوي، والدنيوي ضربان، نفع ضروري، ونفع غير ضروري، فالضروري كالأكل والجماع اللذين لو تصورناهما مرتفعين لارتفع بارتفاع الجماع نوع الحيوان ... والخمر نفعها دنيوي غير ضروري ... وليس ذلك بضروري ولا متحقق النفع فيه، وفيهما إثم متحقق أو مظنون، والعقل يقتضي أن يتحاشى من التزام الإثم المظنون للنفع المتحقق الذي ليس بضروري، فكيف من النفع المظنون؟ ... لما أراد الله تبارك وتعالى تحريم الخمر على الناس لما رأى في ذلك من المصلحة، وعلم من غريزتهم التي غرزها عليها إن كثيرا منهم إذا ردع عما ألفه واستحسنه لا يكاد يرتدع ابتدأ بتقبيح السكر في نفوسهم، ولكونه منافيا لذكر الله وعبادته، فقال: ﴿لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ﴾ فلما رسخ ذلك في نفوسهم أنزل قوله: ﴿قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ﴾، وكأن في هذا إشارة لا يعرفها إلا ذوو العقول الراجحة، فلما قوي ذلك في نفوسهم قال تعالى: ﴿إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ﴾", "en": "\"Their sin is greater than their benefit\": with these words, he says, Allah pointed to the prohibition of wine and gambling in a subtle way that needs a premise to uncover. Benefit is either religious or worldly; worldly benefit is either necessary — like eating and intimacy, without which the individual and the species would perish — or not necessary. The benefit of wine is worldly and not necessary, and not even certain; while the sin in it is certain, or at least likely. Reason requires avoiding a likely sin even for a certain benefit that is not necessary — so how much more for a doubtful one?\nThen he explains why it came in stages. When Allah willed to forbid wine, for the good He saw in that, He knew of the nature He gave people that many, when held back from what they are used to and like, can hardly stop at once. So He began by making drunkenness ugly to them, as something that clashes with remembering and worshipping Him — \"do not come near the prayer while drunk, until you know what you are saying\"; when that had settled, He revealed this verse, a hint only people of sound mind would catch; and when that had grown strong in them: \"wine, gambling, idols and divining arrows are filth, of Satan's work — so avoid it … will you not stop?\"\n(The hadith of 'Umar in Abu Dawud and at-Tirmidhi gives the first two the other way round: this verse first, then the one on prayer, then al-Ma'idah — and when that was recited 'Umar said, \"We have stopped.\" Either way, the lesson ar-Raghib draws stands: people were weaned from it step by step.)\nGambling is like it, though its matter was lighter; some counted every wager and game of chance as maysir, others judged them by analogy to it — and the Prophet ﷺ said, \"whoever plays with dice has disobeyed Allah and His Messenger\".", "ar": "أشار الله بقوله ﴿وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ﴾ إلى التحريم إشارةً لطيفةً تحتاج في كشفها إلى مقدّمة: النفع ضربان: دينيٌّ ودنيويّ؛ والدنيويّ ضربان: ضروريٌّ كالأكل والجماع اللذين لو ارتفعا لارتفع بارتفاع الجماع نوع الحيوان وبارتفاع الأكل أشخاصه، وغير ضروريّ. والخمر نفعها دنيويٌّ غير ضروريّ، وليس متحقّق النفع، وفيها إثمٌ متحقّقٌ أو مظنون؛ والعقل يقتضي أن يُتحاشى من التزام الإثم المظنون للنفع المتحقّق الذي ليس بضروريّ، فكيف للنفع المظنون؟\nولمّا أراد الله تحريم الخمر لما رأى في ذلك من المصلحة، وعلم من غريزة الناس أن كثيرًا منهم إذا رُدع عمّا ألفه واستحسنه لا يكاد يرتدع، ابتدأ بتقبيح السكر في نفوسهم لكونه منافيًا لذكر الله وعبادته: ﴿لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ﴾؛ فلمّا رسخ ذلك أنزل ﴿قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ﴾ — إشارةً لا يعرفها إلا ذوو العقول الراجحة —؛ فلمّا قوي ذلك في نفوسهم قال: ﴿إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ﴾.\n(وفي حديث عمر عند أبي داود والترمذي أن آية البقرة نزلت أوّلًا، ثم آية النساء، ثم آية المائدة، فلمّا قُرئت عليه قال: «انتهينا». وعلى الترتيبين يبقى ما استنبطه الراغب: أنهم فُطموا عنها شيئًا فشيئًا.)\nوعلى قريبٍ من هذا الكلام في الميسر، لكن أمره أخفّ؛ ومن الناس من جعل كلّ ما فيه خطرٌ ومقامرةٌ ميسرًا، ومنهم من قاسه عليه؛ وقد قال ﷺ: «من لعب بالنرد فقد عصى الله ورسوله».", "links": [{"ref": "4:43", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ﴾", "en": "The stage on prayer", "ar": "مرحلة الصلاة"}, {"ref": "5:90", "q": "﴿إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ﴾", "en": "The last word: avoid it", "ar": "الكلمة الأخيرة: فاجتنبوه"}, {"ref": "5:91", "q": "﴿إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ﴾", "en": "The harm, named: enmity, and turning from prayer", "ar": "الضرر مسمًّى: العداوة والصدّ عن الصلاة"}], "v": 1, "p": 450, "pe": 451, "sid": 451},
  {"a": [219, 219], "h": "\"They ask what they should spend — say: what is beyond your need\": why the same question got a new answer", "hAr": "﴿وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ﴾ — لماذا جاء السؤال نفسه بجوابٍ آخر", "said": "قيل: أما الأول: فسؤال عن الجنس الذي ينفق، وعمن ينفق عليه، فبين لهم الأمران، وأما السؤال هاهنا فعن القدر المنفق، فأجيبوا بحسبه، فبين أن الذي ينفق هو العفو، وقال ابن عباس: هو الفضل عن الغني ... وقال الحسن وعطاء: هو القصد الذي لا إسراف فيه ولا إقتار، وقال مجاهد: هو الصدقة المفروضة، وكل ذلك مراد، فإن أقل ما تطيب به نفس المسلم هو الصدقة الواجبة، ومن لم تطب نفسه فليس بتام الإيمان، ثم منهم من تطيب نفسه ببذل جل ماله، ومنهم من تطيب بكل ماله، كأبي بكر- رضي الله عنه- فإذن العفو متناول لما هو واجب ولما هو تبرع ... وقوله: ﴿كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ﴾ فيه حث على تجنب الخمر والميسر، وتنبيه على تحريمهما، فإن في التفكر في الدنيا والآخرة معرفتهما ومعرفة منافعهما، وأن النفع القليل في الدنيا لا يجب أن يشترى بكثير الإثم في الآخرة", "en": "The same question — \"what should they spend?\" — was asked at 2:215 and answered differently. Why? The first asked about the kind of thing to spend and on whom, and both were made clear; this one asks about the amount, and is answered accordingly: al-'afw.\nIbn 'Abbas said it is what is left over beyond one's needs; al-Hasan and 'Ata': the middle way, with neither waste nor stinginess; Mujahid: the obligatory charity. All are meant, says ar-Raghib. The least a Muslim gives willingly is the obligatory charity — and whoever does not give that willingly is not complete in faith; then some give most of their wealth gladly, and some all of it, like Abu Bakr. So al-'afw takes in both the obligatory and the voluntary.\n\"Thus Allah makes the signs clear to you, that you may reflect — on this world and the next\": this urges avoiding wine and gambling and hints at their prohibition; for reflecting on both worlds shows what each is worth — and that a small benefit in this world should not be bought with much sin in the next.", "ar": "فإن قيل: كيف أُعيد السؤال عمّا ينفقون، وقد أُجيب عنه قبلُ؟ قيل: الأوّل سؤالٌ عن الجنس الذي يُنفَق وعمّن يُنفَق عليه، فبُيّن لهم الأمران؛ وأمّا هنا فعن القَدْر المُنفَق، فأُجيبوا بحسبه: ﴿قُلِ ٱلۡعَفۡوَۗ﴾.\nقال ابن عبّاس: هو الفضل عن الغنى؛ وقال الحسن وعطاء: القصد الذي لا إسراف فيه ولا إقتار؛ وقال مجاهد: الصدقة المفروضة. وكلّ ذلك مراد: فأقلّ ما تطيب به نفس المسلم الصدقة الواجبة، ومن لم تطب نفسه بها فليس بتامّ الإيمان؛ ثم منهم من تطيب نفسه ببذل جُلّ ماله، ومنهم من تطيب بكلّ ماله كأبي بكرٍ رضي الله عنه؛ فالعفو متناولٌ لما هو واجبٌ ولما هو تبرّع.\nو﴿كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ﴾: حثٌّ على تجنّب الخمر والميسر وتنبيهٌ على تحريمهما، فإن في التفكّر في الدنيا والآخرة معرفتهما ومعرفة منافعهما، وأن النفع القليل في الدنيا لا يجب أن يُشترى بكثير الإثم في الآخرة.", "links": [{"ref": "2:215", "q": "﴿يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ﴾", "en": "The first answer: the kind, and on whom", "ar": "الجواب الأوّل: الجنس ومن يُنفَق عليه"}, {"ref": "25:67", "q": "﴿وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا﴾", "en": "The middle way in spending", "ar": "القصد في الإنفاق"}, {"ref": "17:29", "q": "﴿وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ﴾", "en": "Neither tight-fisted nor wasteful", "ar": "لا بخلٌ ولا تبذير"}], "v": 1, "p": 452, "pe": 452, "sid": 453},
  {"a": [220, 220], "h": "\"They ask you about orphans\" — living alongside them is allowed; Allah knows the intention", "hAr": "﴿وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحٞ لَّهُمۡ خَيۡرٞۖ﴾ — الخلطة جائزة، والله يعلم النيّة", "said": "ولما أكثر الله تعالى التحذير من مال اليتيم في نحو قوله: ﴿وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ﴾ وقوله: ﴿إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ﴾، وقوله: ﴿وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ﴾ الآية، تحرجوا عن تناول ماله ومخالطته، فبين تعالي أن حق الإنسان أن يتحرى الصلاح له، وأن لا ضير في مخالطته أي مصاهرته. وسائر أنواع المخالطة، وبين أنه أخوهم، وذلك إشارة إلى نحو قوله: ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ﴾ ... ونبه بقوله: ﴿وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ﴾ أن الله تعالى لا تخفى عليه مقاصد الإنسان فيما يفعله معهم، وبين بقوله: ﴿وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ﴾ أنه لم يقصد إعناتا فيما أوصاهم به في هذه الآيات المختلفة", "en": "Allah had warned so often about orphans' property — \"do not come near the orphan's property except in the best way\", \"those who consume orphans' wealth…\", \"give the orphans their property\" — that people grew afraid even to touch it or to live alongside them. So He made clear that one's duty is to seek what is good for the orphan, and that there is no harm in mixing with them — by marriage and every other way of living together; the orphan is your brother, as \"the believers are brothers\".\n\"Allah knows the one who spoils from the one who sets right\": nothing of a person's intentions in what he does with them is hidden from Allah. And \"had Allah willed, He would have put you in hardship\" shows that He intended no hardship in all He enjoined in these different verses.\nKhalt, mixing, is joining the parts of two things, liquid or not — wider than mazj, blending; a friend is called khalit, a step below khalil. I'nat, putting in hardship, comes from a bone that suffers a crack or a break; anything that brings sin or strain is 'anat.", "ar": "لمّا أكثر الله التحذير من مال اليتيم — ﴿وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ﴾، و﴿إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا﴾، و﴿وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ﴾ — تحرّجوا من تناول ماله ومخالطته؛ فبيّن تعالى أن حقّ الإنسان أن يتحرّى الصلاح له، وأن لا ضير في مخالطته — بالمصاهرة وسائر أنواع المخالطة —، وأنه أخوهم، إشارةً إلى نحو ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ﴾.\nونبّه بقوله ﴿وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ﴾ أن الله لا تخفى عليه مقاصد الإنسان فيما يفعله معهم؛ وبيّن بقوله ﴿وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ﴾ أنه لم يقصد إعناتًا فيما أوصاهم به في هذه الآيات المختلفة.\nو«الخلط» الجمع بين أجزاء شيئين، مائعَين كانا أو غير مائعَين، فهو أعمّ من المزج، ويُقال للصديق «الخليط» وهو دون الخليل. و«الإعنات» من «عنِت العظمُ» إذا أصابه وهْيٌ أو كسر، وكلّ ما يُؤثِم أو يشقّ عنَت.", "links": [{"ref": "6:152", "q": "﴿وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ﴾", "en": "The warning that made them afraid", "ar": "التحذير الذي أخافهم"}, {"ref": "4:10", "q": "﴿إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ﴾", "en": "Why they were afraid", "ar": "لماذا خافوا"}, {"ref": "49:10", "q": "﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ﴾", "en": "\"They are your brothers\"", "ar": "«فإخوانكم»"}], "v": 1, "p": 453, "pe": 453, "sid": 454},
  {"a": [221, 221], "h": "\"A believing slave-woman is better than a polytheist, even if she pleases you\" — how to weigh two things, and why looks do not decide", "hAr": "﴿وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ﴾ — كيف تُوزن المفاضلة، ولماذا لا يحكم الإعجاب", "said": "والنهي عن نكاح المشركات عام فيمن ليس من أهل الكتاب ولم يدخل في ذلك أهل الكتاب لقوله: ﴿وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾، فإن قيل: فقد قال تعالى: ﴿لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ﴾، الآية، والنكاح يجب المودة لقوله: ﴿أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ﴾، وقد نهانا عن مودتهم، فيجب أن لا نواصلهم! قيل: المودة النهي عنها هي الدينية لا المودة النفعية أو الشهوية ... مثاله أن من شك في العلم والغنى أيهما أفضل؟ نقول: انظر هل الغنى مع الجهل أفضل؟ أم الفقر مع العلم؟ فإذا علمت أن الفقر مع العلم أفضل من الجهل مع الغنى علمت أن العلم أفضل من الغنى ... فالعبد هو الذي ملك منافعه مدة، والحر هو الذي لم يملك منافعه، والمؤمن هو المستحق للثواب الدائم، والمشرك هو المستحق للعقاب الدائم، فينظر هل من ملك منافعه مدة ثم أثيب دائما أفضل؟ ... فإذا علمنا أن الأول خير، علمنا أن العبد المؤمن خير من الحر المشرك ... فليس الإعجاب إلا من ثمرة الجهل بحقيقة الشيء والجهل لا يوجب حكما، فإذن لا اعتبار بإعجابكم", "en": "The ban on marrying polytheist women covers those who are not People of the Book; the People of the Book are not included, because of \"and the chaste women of those given the Book before you\" (5:5). (That permission is for men; a believing woman is married only to a believer — 60:10.)\nAn objection: \"you will not find people who believe in Allah and the Last Day loving those who oppose Allah and His Messenger\" — and marriage brings love: \"He placed between you affection and mercy\". Must we then keep away from them altogether? Ar-Raghib: the love forbidden is love for their religion — not the affection that comes from benefit or desire; if we feel affection for one of them for some benefit, it is the benefit we love.\n\"A believing slave is better than a free polytheist\" needs a way of weighing. When you doubt which of two things is better, pair each with the opposite of the other. Knowledge or wealth? Ask: is wealth with ignorance better, or poverty with knowledge? Once you see that poverty with knowledge is better, you know that knowledge is better than wealth. So: a slave is one whose work is owned by another for a time, the free one whose work is not; the believer is owed lasting reward, the polytheist lasting punishment. Who is better — one whose work was owned for a while and who is then rewarded forever, or one whose work was his own for a while and who is then punished forever? Once we see that the first is better, we know that a believing slave is better than a free polytheist.\n\"Even if she pleases you\": being taken with someone comes only from not knowing their true state, and not knowing decides nothing — so your being pleased counts for nothing.", "ar": "النهي عن نكاح المشركات عامٌّ فيمن ليس من أهل الكتاب، ولم يدخل فيه أهل الكتاب لقوله: ﴿وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ﴾. (وهذه الرخصة للرجال؛ أمّا المؤمنة فلا تُنكَح إلا لمؤمن: ﴿لَا هُنَّ حِلّٞ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ﴾.)\nفإن قيل: قد قال تعالى: ﴿لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ﴾، والنكاح يوجب المودّة: ﴿وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ﴾، وقد نُهينا عن مودّتهم، فيجب ألّا نواصلهم؟ قيل: المودّة المنهيّ عنها هي الدينيّة، لا المودّة النفعيّة أو الشهويّة؛ فإنّا إذا وددناهم لنفعٍ ما فإنما نودّ النفع.\nوفي ﴿وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ﴾ إشارةٌ إلى فضل العبد المؤمن على الحرّ المشرك، وبيانه يحتاج إلى مقدّمة: الشيئان إذا شُكّ أيّهما أفضل، أُخذ كلٌّ منهما مع ضدّ الآخر. مثاله: من شكّ في العلم والغنى أيّهما أفضل، نقول: انظر، هل الغنى مع الجهل أفضل، أم الفقر مع العلم؟ فإذا علمت أن الفقر مع العلم أفضل علمت أن العلم أفضل من الغنى. فالعبد من مُلكت منافعه مدّة، والحرّ من لم تُملك منافعه، والمؤمن مستحقٌّ للثواب الدائم، والمشرك مستحقٌّ للعقاب الدائم؛ فيُنظر: أمن مُلكت منافعه مدّةً ثم أُثيب دائمًا أفضل، أم من لم تُملك منافعه مدّةً ثم عوقب دائمًا؟ فإذا علمنا أن الأوّل خير، علمنا أن العبد المؤمن خيرٌ من الحرّ المشرك.\nونبّه بقوله ﴿وَلَوۡ أَعۡجَبَتۡكُمۡۗ﴾ أن لا اعتبار بإعجابكم، فليس الإعجاب إلا من ثمرة الجهل بحقيقة الشيء، والجهل لا يوجب حكمًا.", "links": [{"ref": "5:5", "q": "﴿وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ﴾", "en": "The People of the Book: the exception", "ar": "أهل الكتاب: الاستثناء"}, {"ref": "60:10", "q": "﴿لَا هُنَّ حِلّٞ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ﴾", "en": "A believing woman marries only a believer", "ar": "المؤمنة لا تُنكَح إلا لمؤمن"}, {"ref": "30:21", "q": "﴿وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ﴾", "en": "What marriage brings: affection and mercy", "ar": "ما يجلبه الزواج: المودّة والرحمة"}], "v": 1, "p": 454, "pe": 455, "sid": 455},
  {"a": [221, 221], "h": "\"They invite to the Fire, and Allah invites to Paradise … that they may remember\" — what it is we are to remember", "hAr": "﴿أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ﴾ — وما الذي نتذكّره", "said": "ونبه - عز وجل - على تحريم مواصلة المشركين بقوله: ﴿أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ﴾ أي إلى الأفعال الموجبة للنار، وواجب اجتناب الداعي إلى النار الحامل عليها فواجب مجانبتهم إذن ... ثم قال: ﴿وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ﴾، والداعي إلى الجنة واجب إتباعه، وعلى هذا دل قوله - عز وجل - حكاية عمن أخبر عنه: ﴿مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى ٱلنَّارِ﴾ ... وحقيقة التذكر الاستدراك عن نسيان أو غفلة لما استثبته القلب ... إن قيل: إلى أي شيء أشار بهذا التذكر؟ قيل: إن الله عز وجل - ركز فينا بالفطرة معرفته ومعرفة آلائه، والإنسان باستفادة العلم يتذكر ما ركز فيه، فهذا معنى التذكر ... قالوا: وقد عرفنا الطريق الذي به يتوصل إلى هذا التذكر بقوله: ﴿إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ﴾ فبين أنكم إذا فعلتم ذلك رجوتم تذكر هذه الحالة", "en": "\"They invite to the Fire\" — to the deeds that bring it; and one must keep away from whoever calls to the Fire and draws others to it. So the verse forbids binding oneself to them in marriage. \"And Allah invites to Paradise and forgiveness\" — and whoever calls to Paradise must be followed, as the believer among Pharaoh's people said: \"why is it that I call you to salvation, while you call me to the Fire?\" \"By His leave\": by His knowledge and His command, and by His signs and proofs, of reason and of revelation.\n\"That they may remember\": to remember is to recover, after forgetting or heedlessness, what the heart once held firm. What, then, is to be remembered? Allah planted in us, in our very nature, knowledge of Him and of His favours; by learning, a person remembers what was planted in him. That is what remembering means. Others said: whoever clears the veils from his heart remembers what Allah said to him when \"your Lord took from the children of Adam their descendants\" and made them bear witness. And they said the way to that remembrance is shown in \"Allah commands justice, excellence, and giving to relatives, and forbids indecency, wrong and oppression; He admonishes you so that you may remember\": do these, and you may hope to remember that state.", "ar": "﴿أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ﴾: إلى الأفعال الموجبة للنار؛ والداعي إلى النار الحامل عليها واجبٌ اجتنابه، فمجانبتهم إذن واجبة — وبذلك نبّه على تحريم مواصلة المشركين بالنكاح. ثم قال ﴿وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ﴾، والداعي إلى الجنّة واجبٌ اتّباعه، وعلى هذا دلّ قول مؤمن آل فرعون: ﴿وَيَٰقَوۡمِ مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى ٱلنَّارِ﴾. و﴿بِإِذۡنِهِۦۖ﴾: بعلمه وأمره، وآياته وحججه ودلائله العقليّة والشرعيّة.\nو﴿لَعَلَّهُمۡ يَتَذَكَّرُونَ﴾: حقيقة التذكّر الاستدراك عن نسيانٍ أو غفلةٍ لما استثبته القلب. فإن قيل: إلى أيّ شيءٍ أشار بهذا التذكّر؟ قيل: ركز الله فينا بالفطرة معرفته ومعرفة آلائه، والإنسان باستفادة العلم يتذكّر ما رُكز فيه — فهذا معنى التذكّر. وقال قوم: من دفع عن قلبه الأغشية تذكّر ما قال الله له ودلّ عليه بقوله ﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾؛ قالوا: وقد عرّفنا الطريق الذي يُتوصّل به إلى هذا التذكّر بقوله ﴿إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ﴾: فإذا فعلتم ذلك رجوتم تذكّر هذه الحالة.", "links": [{"ref": "40:41", "q": "﴿وَيَٰقَوۡمِ مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى ٱلنَّارِ﴾", "en": "Two callers", "ar": "داعيان"}, {"ref": "7:172", "q": "﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾", "en": "What the heart once knew", "ar": "ما عرفه القلب أوّلًا"}, {"ref": "16:90", "q": "﴿إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ﴾", "en": "The way to remembering", "ar": "طريق التذكّر"}], "v": 1, "p": 455, "pe": 456, "sid": 456},
  {"a": [222, 222], "h": "\"They ask you about menstruation — say: it is harm\": the middle way between two extremes", "hAr": "﴿وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى﴾ — الوسط بين طرفين", "said": "والأذى: اسم لما ينال النفس منه مكروه، ولهذا سمي الله تعالى الكلام المكروه أذى، فقال: ﴿وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ﴾ ... ولما كان الناس في مجامعة المرأة في حال الحيض بين إفراط وتفريط فإن اليهود كانوا إذا حاضت المرأة لم يؤاكلوها ولم يجتمعوا معها في البيوت وبعض النصارى لم يتحاش من مجامعتها، فسئل - عليه السلام -، فقال تعالى: ﴿هُوَ أَذٗى﴾ تنبيها أن العقل يقتضي تجنبه ... ولما كان الإنسان قد يتحمل الأذى ولا يراه محرما صرح بتحريمه بقوله: ﴿فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ﴾ ... ولما كان الاعتزال قولا مشتركا ويكنى به عن العدول عنها عند الفراغ وعن مجانبة ذلك الموضع وعن مجانبتها رأسا، قال تعالى: «ولا تقربوهن» ليدل باللفظتين الكنايتين على مجانبة مباضعتها، وعلى جواز التمتع بها منها دون الفرج المدلول عليه بقول النبي - عليه السلام: \" اصنعوا كل شيء إلا الجماع \"", "en": "Adha, harm, is anything hurtful that reaches the soul — which is why Allah calls hurtful words \"adha\": \"you will hear much harm from those given the Book before you and from the idolaters\".\nPeople stood between two extremes about a woman in her period: the Jews would not eat with her or share a house with her, while some Christians did not even avoid intimacy with her. The Prophet ﷺ was asked, and Allah answered \"it is harm\" — showing that reason itself calls for avoiding it. And since a person may put up with a harm without thinking it forbidden, He forbade it outright: \"so keep away from women during menstruation\".\n\"Keep away\" can mean several things — leaving her bed, avoiding that one place, or avoiding her altogether — so He added \"do not come near them\": the two phrases, both courteous allusions, together forbid intercourse while allowing every other closeness, as the Prophet ﷺ said: \"do everything except intercourse\".", "ar": "«الأذى» اسمٌ لما ينال النفس منه مكروه، ولهذا سمّى الله الكلام المكروه أذًى: ﴿وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ﴾.\nولمّا كان الناس في مجامعة المرأة حال الحيض بين إفراطٍ وتفريط — فاليهود إذا حاضت المرأة لم يؤاكلوها ولم يجتمعوا معها في البيوت، وبعض النصارى لم يتحاشَ من مجامعتها —، سُئل النبيّ ﷺ، فقال تعالى ﴿هُوَ أَذٗى﴾، تنبيهًا أن العقل يقتضي تجنّبه؛ ولمّا كان الإنسان قد يتحمّل الأذى ولا يراه محرّمًا، صرّح بتحريمه: ﴿فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ﴾.\nولمّا كان «الاعتزال» لفظًا مشتركًا يُكنى به عن العدول عنها، وعن مجانبة ذلك الموضع، وعن مجانبتها رأسًا، قال «ولا تقربوهن» ليدلّ باللفظتين الكنايتين على مجانبة مباضعتها، وعلى جواز التمتّع بها دون الفرج، كما قال ﷺ: «اصنعوا كلّ شيءٍ إلا الجماع».", "links": [{"ref": "2:143", "q": "﴿وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا﴾", "en": "The middle nation, between two extremes", "ar": "الأمّة الوسط بين طرفين"}, {"ref": "2:223", "q": "﴿نِسَآؤُكُمۡ حَرۡثٞ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ﴾", "en": "The next verse: what is allowed", "ar": "الآية التالية: ما أُبيح"}], "v": 1, "p": 456, "pe": 457, "sid": 457},
  {"a": [222, 222], "h": "\"Allah loves those who repent, and loves those who purify themselves\" — why repentance comes first", "hAr": "﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ﴾ — لماذا قُدّمت التوبة", "said": "ولما كان لفظ «يطهر» يقال فيما كان طاهرا بنفسه وفيما كان يتطهر، نبه بقوله: ﴿فَإِذَا تَطَهَّرۡنَ﴾ أنه لم يرد إلا الطهارة عن تطهر ... فدل ذلك أن لا يصح وطؤها ما لم تغتسل ... وقوله: ﴿فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ﴾ إشارة إلى مراعاة كل ما أمر به من أحكام النكاح ... ثم قال: ﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ﴾ تنبيها أن من كان منه شيء من ذلك، فحق عليه أن يتوب ويتطهر من بعد، والتطهر عام في استعمال الماء، وتطهر القلوب من الذنوب والتوبة اجتناب الذنب والتطهر عمل الصالحات، وجعل التوبة مقدمة على التطهير تنبيها أن اجتناب القاذورات مدرجة إلى فعل الخيرات، وعظم أمر المتطهرين حيث جعلهم محبوبيه", "en": "\"Being pure\" is said of what is clean in itself and of what has been made clean; so \"when they have purified themselves\" shows He meant the purity that comes from purifying — washing. The other reading, \"until they purify themselves\" (yattahharna), confirms it: so, he says, she is not approached until she has washed. \"Then come to them as Allah has commanded you\" — keeping every rule He gave for marriage.\n\"Allah loves those who repent\": whoever has done any of this should repent and purify himself afterwards. Purifying is general — with water, and of hearts from sins. Repentance is leaving sin; purifying is doing good. Repentance is put first to show that avoiding what is filthy is the step up to doing good; and He raised those who purify themselves by making them His beloved — as He said of the people of a mosque founded on God-consciousness: \"in it are men who love to purify themselves, and Allah loves those who purify themselves\".", "ar": "لمّا كان لفظ «يطهر» يُقال فيما كان طاهرًا بنفسه وفيما تطهّر، نبّه بقوله ﴿فَإِذَا تَطَهَّرۡنَ﴾ أنه لم يُرد إلا الطهارة عن تطهّر، ويؤكّده قراءة من قرأ «حتى يطّهّرن» بالتشديد، فدلّ ذلك أن لا يصحّ وطؤها ما لم تغتسل. و﴿فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ﴾: إشارةٌ إلى مراعاة كلّ ما أمر به من أحكام النكاح.\nثم قال ﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ﴾ تنبيهًا أن من كان منه شيءٌ من ذلك فحقٌّ عليه أن يتوب ويتطهّر من بعد. والتطهّر عامٌّ في استعمال الماء وتطهير القلوب من الذنوب؛ والتوبة اجتناب الذنب، والتطهّر عمل الصالحات؛ وجعل التوبة مقدّمةً على التطهّر تنبيهًا أن اجتناب القاذورات مدرجةٌ إلى فعل الخيرات؛ وعظّم أمر المتطهّرين حيث جعلهم محبوبيه، كما قال: ﴿فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ﴾.", "links": [{"ref": "9:108", "q": "﴿فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ﴾", "en": "Those who love to purify themselves", "ar": "يحبّون أن يتطهّروا"}, {"ref": "5:6", "q": "﴿مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ﴾", "en": "Purity is what the law aims at", "ar": "الطهارة غاية التشريع"}, {"ref": "66:8", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا﴾", "en": "Sincere repentance", "ar": "التوبة النصوح"}], "v": 1, "p": 457, "pe": 458, "sid": 458}
];
